// AiXenix Cosmos Lab web client: number and distance formatting for the universe map.

import type { Lang } from '../../content/catalog';
import { formatNumber, formatSpan, YEAR } from '../../app/units';

export const LY_PER_PC = 3.261563777;
const AU_PER_PC = 206264.806;

/** Distance with a natural unit (au, pc, kpc, Mpc) and light-years in brackets. */
export function formatDistance(pc: number, lang: Lang, withLy = true): string {
  const L = (en: string, ru: string) => (lang === 'ru' ? ru : en);
  if (!Number.isFinite(pc)) return '—';
  let main: string;
  if (pc < 0.05) main = `${formatNumber(pc * AU_PER_PC, lang, 3)} ${L('au', 'а. е.')}`;
  else if (pc < 1000) main = `${formatNumber(pc, lang, 3)} ${L('pc', 'пк')}`;
  else if (pc < 1e6) main = `${formatNumber(pc / 1000, lang, 3)} ${L('kpc', 'кпк')}`;
  else main = `${formatNumber(pc / 1e6, lang, 3)} ${L('Mpc', 'Мпк')}`;
  if (!withLy || pc < 0.05) return main;
  const ly = pc * LY_PER_PC;
  const lyText = ly < 1e6 ? `${formatNumber(ly, lang, 3)} ${L('ly', 'св. лет')}` : `${formatNumber(ly / 1e6, lang, 3)} ${L('million ly', 'млн св. лет')}`;
  return `${main} (${lyText})`;
}

/** Time light needs for a distance, e.g. "2.5 million yr". */
export function lightTime(pc: number, lang: Lang): string {
  return formatSpan(pc * LY_PER_PC * YEAR, lang, 3);
}

export function formatCount(n: number, lang: Lang): string {
  if (!Number.isFinite(n)) return '—';
  if (n < 1e6) return new Intl.NumberFormat(lang === 'ru' ? 'ru-RU' : 'en-US').format(Math.round(n));
  return formatNumber(n, lang, 3);
}
