// AiXenix Cosmos Lab web client: the universe map renderer (Three.js).
//
// Scales from the Local Group (Mpc) down to single stars (au): 1 render unit = 1 parsec around a floating origin (the
// camera target) with a logarithmic depth buffer. What is drawn, and what it means:
//  - galaxy glows and density splats: a drawing of the model's coarse cells (each splat stands for many model stars);
//  - nearby stars: real addressable stars of the model (or observed catalogue stars) from a bounded query; only these,
//    observed stars and galaxies are selectable;
//  - flights: camera animations on the map. No galaxy dynamics are computed here.

import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { blackbodyColor } from '../app/astro';

export type Vec3 = [number, number, number];

/** A galaxy as the map draws it (mapped from the cosmos model by the page's adapter). */
export interface MapGalaxy {
  id: string;
  centrePc: Vec3;
  /** Unit vectors in the universe frame: disk normal and major axis. */
  normal: Vec3;
  majorAxis: Vec3;
  radiusPc: number;
  thicknessPc: number;
  /** 'spiral' | 'barred_spiral' | 'lenticular' | 'elliptical' | 'irregular' | 'dwarf_irregular' | 'dwarf_spheroidal' ... */
  kind: string;
  modelStarCount: number;
  /** Optional shape hints for the far-view glow (fractions of radiusPc, degrees). */
  diskScale?: number;
  bulgeScale?: number;
  arms?: number;
  pitchDeg?: number;
  axisRatio?: number;
}

/** A selectable star: an exact model star or an observed catalogue star. */
export interface MapStar {
  /** Address (procedural, e.g. c1.milky_way.1x2f) or 'obs.<id>' (observed). */
  id: string;
  provenance: 'observed' | 'procedural';
  galaxyId: string;
  positionPc: Vec3;
  teffK: number;
  luminositySun: number;
  /** Names in both languages (designation for model stars). */
  name: { en: string; ru: string };
  /** Anything else the page needs (the original record). */
  raw: unknown;
}

/**
 * A drawing sample of a galaxy. `ids` present: real model stars (each id resolves to the drawn point exactly); absent:
 * density cells (decoration of the model's coarse distribution, never selectable). `frame` says whether positions are
 * galaxy-local (x = major axis, z = normal) or already in the universe frame, relative to the galaxy centre.
 */
export interface DrawSample {
  galaxyId: string;
  count: number;
  ids: Float64Array | null;
  frame: 'galaxy' | 'universe';
  positions: Float32Array;
  colors: Float32Array;
  brightness: Float32Array;
  /** Model stars the whole sample stands for (the galaxy's capacity or a region's count). */
  represents: number;
}

export interface NearResult {
  stars: MapStar[];
  modelCountInRadius: number;
  truncated: boolean;
}

export interface UniverseProvider {
  galaxies: MapGalaxy[];
  observed: MapStar[];
  sunPc: Vec3;
  /** Drawing sample of real model stars (may run in a worker). */
  sample(galaxyId: string, count: number): Promise<DrawSample | null>;
  /** Exact model stars inside a sphere, bounded. */
  near(galaxyId: string, centrePc: Vec3, radiusPc: number, maxStars: number): NearResult | null;
  /** The exact model star behind a sample id. */
  starById(galaxyId: string, id: number): MapStar | null;
  /** Expected model stars per pc³ at a point (to size neighbourhood queries). */
  density(galaxyId: string, positionPc: Vec3): number;
}

/** A navigation region (group, cluster or sky region) as the map draws it. */
export interface MapRegion {
  id: string;
  parent: string | null;
  centrePc: Vec3;
  radiusPc: number;
  members: string[];
  /** Root-level regions are labelled at the widest view; subgroups only inside their parent. */
  depth: number;
  /** Label priority when labels crowd (higher first): home, clusters, groups, navigation lists. */
  priority: number;
}

export type Selection =
  | { kind: 'region'; regionId: string }
  | { kind: 'galaxy'; galaxyId: string }
  | { kind: 'star'; star: MapStar }
  | { kind: 'point'; galaxyId: string; positionPc: Vec3 };

export interface UniverseViewState {
  targetPc: Vec3;
  distancePc: number;
  /** Galaxy the camera is in or nearest to (relative to its size). */
  galaxyId: string | null;
  inside: boolean;
  /** Width of the view at the target distance (pc). */
  viewWidthPc: number;
  sample: { galaxyId: string; shown: number; represents: number } | null;
  near: { radiusPc: number; shown: number; total: number; complete: boolean } | null;
}

export interface FlightProgress {
  t: number; // 0..1
  remainingPc: number;
  speedC: number;
  speedPcPerS: number;
}

export interface UniverseOptions {
  quality: 'low' | 'medium' | 'high';
  bloom: boolean;
  reducedMotion: boolean;
  showLabels: boolean;
}

export interface UniverseEvents {
  onSelect?: (sel: Selection | null) => void;
  onActivate?: (sel: Selection) => void;
  onState?: (s: UniverseViewState) => void;
}

const BIG_SAMPLE = { low: 60000, medium: 140000, high: 260000 } as const;
const FEATURED_GALAXIES = ['milky_way', 'm31', 'lmc', 'smc', 'm33'];
const NEAR_STARS = { low: 1200, medium: 2400, high: 4000 } as const;
const C_PC_PER_S = 9.715611890264e-9; // speed of light in pc/s
const LY_PER_PC = 3.261563777;

const ease = (x: number) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);

function sub3(a: Vec3, b: Vec3): Vec3 {
  return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
}
function len3(a: Vec3): number {
  return Math.hypot(a[0], a[1], a[2]);
}

// ---- shaders --------------------------------------------------------------------------------------------------------

const LOGDEPTH_V = /* glsl */ `
#include <common>
#include <logdepthbuf_pars_vertex>
`;
const LOGDEPTH_F = /* glsl */ `
#include <common>
#include <logdepthbuf_pars_fragment>
`;

/** Density splats of a galaxy sample: per-point world size, flux kept when a splat drops below about a pixel. */
const SPLAT_VERT = /* glsl */ `
${LOGDEPTH_V}
attribute vec3 color;
attribute float aWeight;
uniform float uSplat;
uniform float uFocal;
uniform float uGain;
uniform float uMaxPx;
uniform float uNear;
varying vec3 vColor;
varying float vAlpha;
void main() {
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
  float dist = max(-mv.z, 1e-6);
  float px = uSplat * uFocal / dist;
  float size = clamp(px, 1.5, uMaxPx);
  float flux = sqrt(aWeight) * uGain * min(1.0, (px * px) / (size * size));
  float closeFade = smoothstep(uNear * 1.2, uNear * 5.0, dist);
  vAlpha = clamp(flux, 0.0, 1.6) * closeFade;
  vColor = color;
  gl_PointSize = size;
  #include <logdepthbuf_vertex>
}
`;

const SPLAT_FRAG = /* glsl */ `
${LOGDEPTH_F}
varying vec3 vColor;
varying float vAlpha;
void main() {
  #include <logdepthbuf_fragment>
  vec2 c = gl_PointCoord - 0.5;
  float d2 = dot(c, c) * 4.0;
  if (d2 > 1.0) discard;
  float g = exp(-d2 * 3.2);
  gl_FragColor = vec4(vColor * g * vAlpha, 1.0);
}
`;

/** Stars: apparent size and brightness from luminosity and distance. */
const STAR_VERT = /* glsl */ `
${LOGDEPTH_V}
attribute vec3 color;
attribute float aLum;
attribute float aFlag;
uniform float uScale;
uniform float uFade;
varying vec3 vColor;
varying float vBright;
varying float vFlag;
void main() {
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
  float dist = max(-mv.z, 1e-7);
  float m = log(max(aLum, 1e-6)) / 2.302585 - 2.0 * log(dist) / 2.302585;
  float size = clamp(2.4 + 0.95 * (m + 1.5), 1.6, 11.0) * uScale;
  vBright = clamp(0.55 + 0.22 * (m + 1.5), 0.25, 1.8) * uFade;
  vColor = color;
  vFlag = aFlag;
  gl_PointSize = size;
  #include <logdepthbuf_vertex>
}
`;

const STAR_FRAG = /* glsl */ `
${LOGDEPTH_F}
varying vec3 vColor;
varying float vBright;
varying float vFlag;
void main() {
  #include <logdepthbuf_fragment>
  vec2 c = gl_PointCoord - 0.5;
  float d = length(c) * 2.0;
  if (d > 1.0) discard;
  float core = exp(-d * d * 10.0);
  float halo = exp(-d * 3.0) * 0.35;
  vec3 col = vColor * (core * 1.6 + halo) * vBright;
  gl_FragColor = vec4(col, 1.0);
}
`;

/** Galaxy glow in its own plane (disks) or facing the camera (spheroids): an exponential disk, a bulge and arms. */
const GLOW_VERT = /* glsl */ `
${LOGDEPTH_V}
varying vec2 vUv;
uniform float uBillboard;
uniform float uSize;
void main() {
  vUv = position.xy;
  vec4 mv;
  if (uBillboard > 0.5) {
    mv = modelViewMatrix * vec4(0.0, 0.0, 0.0, 1.0);
    mv.xy += position.xy * uSize;
  } else {
    mv = modelViewMatrix * vec4(position.xy * uSize, 0.0, 1.0);
  }
  gl_Position = projectionMatrix * mv;
  #include <logdepthbuf_vertex>
}
`;

const GLOW_FRAG = /* glsl */ `
${LOGDEPTH_F}
varying vec2 vUv;
uniform vec3 uDiskColor;
uniform vec3 uCoreColor;
uniform float uScaleLen;
uniform float uBulge;
uniform float uBulgeSize;
uniform float uArms;
uniform float uPitch;
uniform float uPhase;
uniform float uAxis;
uniform float uIntensity;
void main() {
  #include <logdepthbuf_fragment>
  vec2 p = vec2(vUv.x, vUv.y / max(uAxis, 0.05));
  float r = length(p);
  if (r > 1.0) discard;
  float disk = exp(-r / max(uScaleLen, 0.02));
  float arms = 1.0;
  if (uArms > 0.5) {
    float th = atan(p.y, p.x);
    float spiral = cos(uArms * (th - log(max(r, 0.02)) / tan(uPitch) - uPhase));
    arms = 0.55 + 0.45 * smoothstep(-0.2, 0.9, spiral) * smoothstep(0.08, 0.3, r);
  }
  float bulge = uBulge * exp(-(r * r) / (2.0 * uBulgeSize * uBulgeSize));
  float edge = smoothstep(1.0, 0.75, r);
  vec3 col = uDiskColor * disk * arms + uCoreColor * bulge;
  gl_FragColor = vec4(col * uIntensity * edge, 1.0);
}
`;

const SKY_VERT = /* glsl */ `
attribute float aSize;
attribute vec3 color;
varying vec3 vColor;
void main() {
  vColor = color;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = aSize;
}
`;
const SKY_FRAG = /* glsl */ `
varying vec3 vColor;
void main() {
  vec2 c = gl_PointCoord - 0.5;
  float d = length(c) * 2.0;
  if (d > 1.0) discard;
  gl_FragColor = vec4(vColor * exp(-d * d * 4.0), 1.0);
}
`;

// ---- galaxy visuals -------------------------------------------------------------------------------------------------

interface GalaxyVisual {
  model: MapGalaxy;
  centre: Vec3;
  rotation: THREE.Quaternion;
  glow: THREE.Mesh;
  glowMat: THREE.ShaderMaterial;
  splats: THREE.Points | null;
  splatCount: number;
  pending: number;
  sample: DrawSample | null;
  splatMat: THREE.ShaderMaterial;
  label: HTMLDivElement;
  screen: THREE.Vector2;
  onScreen: boolean;
  screenRadius: number;
}

const DISK_KINDS = new Set(['spiral', 'barred_spiral', 'lenticular', 'irregular', 'dwarf_irregular']);

function galaxyIntensity(m: MapGalaxy): number {
  // Brighter for bigger galaxies, compressed so dwarfs stay visible.
  return THREE.MathUtils.clamp(0.25 + 0.11 * Math.log10(Math.max(m.modelStarCount, 1)), 0.35, 1.6);
}

/** Rotation galaxy frame (x = major axis, z = normal) -> universe frame. */
function galaxyRotation(m: MapGalaxy): THREE.Quaternion {
  const x = new THREE.Vector3(...m.majorAxis).normalize();
  const z = new THREE.Vector3(...m.normal).normalize();
  const y = new THREE.Vector3().crossVectors(z, x).normalize();
  const xo = new THREE.Vector3().crossVectors(y, z).normalize();
  return new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(xo, y, z));
}

function starColor(teffK: number): [number, number, number] {
  const c = blackbodyColor(teffK || 5000);
  return [c[0] * 0.85 + 0.15, c[1] * 0.85 + 0.15, c[2] * 0.85 + 0.15];
}

// ---- the view -------------------------------------------------------------------------------------------------------

export class UniverseView {
  private readonly renderer: THREE.WebGLRenderer;
  private readonly composer: EffectComposer;
  private readonly bloom: UnrealBloomPass;
  private readonly scene = new THREE.Scene();
  private readonly skyScene = new THREE.Scene();
  readonly camera: THREE.PerspectiveCamera;
  private readonly skyCamera: THREE.PerspectiveCamera;
  private readonly controls: OrbitControls;
  private readonly labelLayer: HTMLDivElement;
  private readonly quad = new THREE.PlaneGeometry(2, 2);
  private provider: UniverseProvider | null = null;
  private readonly galaxies = new Map<string, GalaxyVisual>();
  private nearPoints: THREE.Points | null = null;
  private nearStars: MapStar[] = [];
  private sampleSerial = 0;
  private nearQuery: { centre: Vec3; radius: number; complete: boolean; t: number } | null = null;
  private nearTotal = 0;
  private readonly obsPoints: THREE.Points;
  private readonly obsMat: THREE.ShaderMaterial;
  private readonly nearMat: THREE.ShaderMaterial;
  private readonly obsLabels = new Map<string, HTMLDivElement>();
  private regions: MapRegion[] = [];
  private readonly regionLabels = new Map<string, HTMLDivElement>();
  private galaxyRegion = new Map<string, string>();
  private readonly sunLabel: HTMLDivElement;
  private readonly selLabel: HTMLDivElement;
  private selection: Selection | null = null;
  private origin: Vec3 = [0, 0, 0];
  private options: UniverseOptions;
  private readonly events: UniverseEvents;
  private flight: {
    from: Vec3;
    to: Vec3;
    d0: number;
    d1: number;
    cruise: number;
    t0: number;
    dur: number;
    resolve: (r: 'arrived' | 'stopped') => void;
    onProgress?: (p: FlightProgress) => void;
  } | null = null;
  private raf = 0;
  private running = true;
  private visible = true;
  private lastState = 0;
  private lastActivity = 0;
  private lastRender = 0;
  private readonly clock = new THREE.Clock();
  private readonly resizeObserver: ResizeObserver;
  private readonly intersection: IntersectionObserver;
  private pointerDown: { x: number; y: number; t: number } | null = null;
  private lastTap = 0;
  private disposed = false;
  private currentGalaxy: string | null = null;
  private readonly tmp = new THREE.Vector3();
  private obsKey = '';

  constructor(private readonly container: HTMLElement, options: UniverseOptions, events: UniverseEvents = {}) {
    this.options = { ...options };
    this.events = events;
    this.renderer = new THREE.WebGLRenderer({ antialias: true, logarithmicDepthBuffer: true, powerPreference: 'high-performance' });
    this.renderer.setPixelRatio(this.pixelRatio());
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.0;
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.setClearColor(0x000000, 1);
    const canvas = this.renderer.domElement;
    canvas.className = 'space-canvas';
    container.appendChild(canvas);
    this.labelLayer = document.createElement('div');
    this.labelLayer.className = 'label-layer uni-labels';
    container.appendChild(this.labelLayer);

    this.camera = new THREE.PerspectiveCamera(50, 1, 1e-7, 1e10);
    this.camera.position.set(0, 2.2e4, 3.2e4);
    this.skyCamera = new THREE.PerspectiveCamera(50, 1, 0.1, 1000);

    this.controls = new OrbitControls(this.camera, canvas);
    this.controls.enableDamping = true;
    this.controls.dampingFactor = 0.08;
    this.controls.rotateSpeed = 0.5;
    this.controls.zoomSpeed = 1.15;
    this.controls.panSpeed = 0.7;
    this.controls.screenSpacePanning = true;
    this.controls.minDistance = 2e-5;
    this.controls.maxDistance = 6e8;
    this.controls.addEventListener('change', () => (this.lastActivity = performance.now()));
    this.controls.addEventListener('start', () => {
      this.lastActivity = performance.now();
      if (this.flight) this.stopFlight();
    });

    this.buildSky();

    this.nearMat = this.starMaterial();
    this.obsMat = this.starMaterial();
    this.obsPoints = new THREE.Points(new THREE.BufferGeometry(), this.obsMat);
    this.obsPoints.frustumCulled = false;
    this.scene.add(this.obsPoints);

    this.sunLabel = this.makeLabel('uni-lbl sun');
    this.selLabel = this.makeLabel('uni-lbl sel');
    this.selLabel.style.display = 'none';

    this.composer = new EffectComposer(this.renderer);
    const skyPass = new RenderPass(this.skyScene, this.skyCamera);
    const mainPass = new RenderPass(this.scene, this.camera);
    mainPass.clear = false;
    mainPass.clearDepth = true;
    this.bloom = new UnrealBloomPass(new THREE.Vector2(256, 256), 0.7, 0.5, 0.82);
    this.bloom.enabled = options.bloom;
    this.composer.addPass(skyPass);
    this.composer.addPass(mainPass);
    this.composer.addPass(this.bloom);
    this.composer.addPass(new OutputPass());

    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(container);
    this.intersection = new IntersectionObserver((entries) => {
      this.visible = entries.some((e) => e.isIntersecting);
    });
    this.intersection.observe(container);
    this.resize();

    canvas.addEventListener('pointerdown', this.onPointerDown);
    canvas.addEventListener('pointerup', this.onPointerUp);
    canvas.addEventListener('dblclick', this.onDblClick);
    canvas.addEventListener('contextmenu', this.onContextMenu);
    this.labelLayer.addEventListener('click', this.onLabelClick);
    this.labelLayer.addEventListener('dblclick', this.onLabelDblClick);
    this.raf = requestAnimationFrame(this.loop);
  }

  // ---- public API --------------------------------------------------------------------------------------------------

  setProvider(p: UniverseProvider): void {
    this.provider = p;
    for (const g of this.galaxies.values()) this.disposeGalaxy(g);
    this.galaxies.clear();
    for (const m of p.galaxies) this.galaxies.set(m.id, this.makeGalaxy(m));
    this.rebuildObserved();
    this.nearQuery = null;
    this.lastActivity = performance.now();
  }

  setOptions(patch: Partial<UniverseOptions>): void {
    const prev = this.options;
    this.options = { ...prev, ...patch };
    this.bloom.enabled = this.options.bloom;
    if (patch.quality && patch.quality !== prev.quality) {
      this.renderer.setPixelRatio(this.pixelRatio());
      this.resize();
      for (const g of this.galaxies.values()) this.dropSplats(g);
      this.nearQuery = null;
    }
    this.labelLayer.classList.toggle('labels-off', !this.options.showLabels);
    this.lastActivity = performance.now();
  }

  setSelection(sel: Selection | null): void {
    this.selection = sel;
    this.lastActivity = performance.now();
  }

  /** Current camera target (universe frame, pc) and distance to it. */
  cameraState(): { targetPc: Vec3; distancePc: number } {
    const t = this.controls.target;
    return { targetPc: [this.origin[0] + t.x, this.origin[1] + t.y, this.origin[2] + t.z], distancePc: this.camera.position.distanceTo(t) };
  }

  /** Places the camera without animation (initial view, route reloads, jumps). */
  place(targetPc: Vec3, distancePc: number, dir?: Vec3): void {
    this.stopFlight();
    const off = this.camera.position.clone().sub(this.controls.target);
    const d = dir ? new THREE.Vector3(dir[0], dir[1], dir[2]).normalize() : off.lengthSq() > 0 ? off.normalize() : new THREE.Vector3(0, 0.55, 0.83).normalize();
    this.origin = [...targetPc] as Vec3;
    this.controls.target.set(0, 0, 0);
    this.camera.position.copy(d.multiplyScalar(Math.max(distancePc, 2e-5)));
    this.camera.updateMatrixWorld();
    this.controls.update();
    this.lastActivity = performance.now();
  }

  /** Animated map flight to a target; resolves when it arrives or is stopped. Reduced motion places instantly. */
  flyTo(targetPc: Vec3, distancePc: number, opts: { speed?: number; onProgress?: (p: FlightProgress) => void } = {}): Promise<'arrived' | 'stopped'> {
    this.stopFlight();
    const from = this.cameraState();
    const delta = len3(sub3(targetPc, from.targetPc));
    if (this.options.reducedMotion) {
      this.place(targetPc, distancePc);
      opts.onProgress?.({ t: 1, remainingPc: 0, speedC: 0, speedPcPerS: 0 });
      return Promise.resolve('arrived');
    }
    const speed = Math.max(0.25, opts.speed ?? 1);
    const dur = THREE.MathUtils.clamp(2.2 + 1.5 * Math.log10(1 + delta / Math.max(from.distancePc, 1e-3)), 2, 12) / speed;
    const cruise = Math.max(from.distancePc, distancePc, delta * 0.55);
    return new Promise((resolve) => {
      this.flight = {
        from: from.targetPc,
        to: [...targetPc] as Vec3,
        d0: Math.max(from.distancePc, 2e-5),
        d1: Math.max(distancePc, 2e-5),
        cruise,
        t0: performance.now(),
        dur: dur * 1000,
        resolve,
        onProgress: opts.onProgress,
      };
    });
  }

  stopFlight(): void {
    const f = this.flight;
    if (!f) return;
    this.flight = null;
    f.resolve('stopped');
  }

  flying(): boolean {
    return this.flight !== null;
  }

  dispose(): void {
    this.disposed = true;
    this.running = false;
    this.stopFlight();
    cancelAnimationFrame(this.raf);
    this.resizeObserver.disconnect();
    this.intersection.disconnect();
    const canvas = this.renderer.domElement;
    canvas.removeEventListener('pointerdown', this.onPointerDown);
    canvas.removeEventListener('pointerup', this.onPointerUp);
    canvas.removeEventListener('dblclick', this.onDblClick);
    canvas.removeEventListener('contextmenu', this.onContextMenu);
    this.controls.dispose();
    for (const g of this.galaxies.values()) this.disposeGalaxy(g);
    this.galaxies.clear();
    if (this.nearPoints) {
      this.nearPoints.geometry.dispose();
    }
    this.obsPoints.geometry.dispose();
    this.nearMat.dispose();
    this.obsMat.dispose();
    this.quad.dispose();
    this.skyScene.traverse((o) => {
      const p = o as THREE.Points;
      if (p.geometry) p.geometry.dispose();
      if (p.material) (p.material as THREE.Material).dispose();
    });
    this.composer.dispose();
    this.renderer.dispose();
    canvas.remove();
    this.labelLayer.remove();
  }

  // ---- building ----------------------------------------------------------------------------------------------------

  private pixelRatio(): number {
    const cap = this.options.quality === 'high' ? 2 : this.options.quality === 'medium' ? 1.5 : 1;
    return Math.min(window.devicePixelRatio || 1, cap);
  }

  private resize(): void {
    const w = Math.max(1, this.container.clientWidth);
    const h = Math.max(1, this.container.clientHeight);
    this.renderer.setSize(w, h, false);
    this.composer.setPixelRatio(this.renderer.getPixelRatio());
    this.composer.setSize(w, h);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
    this.skyCamera.aspect = w / h;
    this.skyCamera.updateProjectionMatrix();
    this.lastActivity = performance.now();
  }

  private makeLabel(cls: string): HTMLDivElement {
    const el = document.createElement('div');
    el.className = cls;
    const dot = document.createElement('span');
    dot.className = 'uni-dot';
    const text = document.createElement('span');
    text.className = 'uni-text';
    el.append(dot, text);
    this.labelLayer.appendChild(el);
    return el;
  }

  private starMaterial(): THREE.ShaderMaterial {
    return new THREE.ShaderMaterial({
      vertexShader: STAR_VERT,
      fragmentShader: STAR_FRAG,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      uniforms: { uScale: { value: this.pixelRatio() }, uFade: { value: 1 } },
    });
  }

  private buildSky(): void {
    // Faint distant galaxies and background light: decoration at infinity (not part of the model).
    const n = 2600;
    const pos = new Float32Array(n * 3);
    const col = new Float32Array(n * 3);
    const size = new Float32Array(n);
    let seed = 7;
    const rnd = () => {
      seed = (seed * 1103515245 + 12345) & 0x7fffffff;
      return seed / 0x7fffffff;
    };
    for (let i = 0; i < n; i++) {
      const z = rnd() * 2 - 1;
      const a = rnd() * Math.PI * 2;
      const r = Math.sqrt(1 - z * z);
      pos[i * 3] = r * Math.cos(a) * 90;
      pos[i * 3 + 1] = z * 90;
      pos[i * 3 + 2] = r * Math.sin(a) * 90;
      const warm = rnd();
      const b = 0.05 + Math.pow(rnd(), 5) * 0.35;
      col[i * 3] = b * (0.8 + warm * 0.3);
      col[i * 3 + 1] = b * 0.85;
      col[i * 3 + 2] = b * (1.05 - warm * 0.2);
      size[i] = (0.8 + Math.pow(rnd(), 3) * 1.8) * this.pixelRatio();
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(size, 1));
    const mat = new THREE.ShaderMaterial({ vertexShader: SKY_VERT, fragmentShader: SKY_FRAG, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending });
    const pts = new THREE.Points(geo, mat);
    pts.frustumCulled = false;
    this.skyScene.add(pts);
  }

  private makeGalaxy(m: MapGalaxy): GalaxyVisual {
    const isDisk = DISK_KINDS.has(m.kind);
    const rotation = galaxyRotation(m);
    const glowMat = new THREE.ShaderMaterial({
      vertexShader: GLOW_VERT,
      fragmentShader: GLOW_FRAG,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
      uniforms: {
        uBillboard: { value: isDisk ? 0 : 1 },
        uSize: { value: m.radiusPc },
        uDiskColor: { value: isDisk ? new THREE.Color(0.55, 0.66, 0.95) : new THREE.Color(0.8, 0.72, 0.6) },
        uCoreColor: { value: new THREE.Color(1.0, 0.82, 0.58) },
        uScaleLen: { value: isDisk ? THREE.MathUtils.clamp(m.diskScale ?? 0.28, 0.08, 0.6) : 0.25 },
        uBulge: { value: isDisk ? (m.kind === 'irregular' || m.kind === 'dwarf_irregular' ? 0.25 : 0.9) : 1.2 },
        uBulgeSize: { value: THREE.MathUtils.clamp(m.bulgeScale ?? (isDisk ? 0.12 : 0.3), 0.04, 0.5) },
        uArms: { value: isDisk ? (m.arms ?? 0) : 0 },
        uPitch: { value: THREE.MathUtils.degToRad(Math.max(5, m.pitchDeg ?? 14)) },
        uPhase: { value: 0 },
        uAxis: { value: isDisk ? 1 : THREE.MathUtils.clamp(m.axisRatio ?? 1, 0.3, 1) },
        uIntensity: { value: galaxyIntensity(m) * 0.35 },
      },
    });
    const glow = new THREE.Mesh(this.quad, glowMat);
    glow.frustumCulled = false;
    glow.renderOrder = -2;
    if (isDisk) glow.quaternion.copy(rotation);
    this.scene.add(glow);
    const splatMat = new THREE.ShaderMaterial({
      vertexShader: SPLAT_VERT,
      fragmentShader: SPLAT_FRAG,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      uniforms: { uSplat: { value: 1 }, uFocal: { value: 1 }, uGain: { value: 1 }, uMaxPx: { value: 28 }, uNear: { value: 1 } },
    });
    const label = this.makeLabel('uni-lbl galaxy');
    label.dataset.galaxy = m.id;
    return {
      model: m,
      centre: m.centrePc,
      rotation,
      glow,
      glowMat,
      splats: null,
      splatCount: 0,
      pending: 0,
      sample: null,
      splatMat,
      label,
      screen: new THREE.Vector2(),
      onScreen: false,
      screenRadius: 0,
    };
  }

  private dropSplats(g: GalaxyVisual): void {
    if (g.splats) {
      g.splats.geometry.dispose();
      g.splats.removeFromParent();
    }
    g.splats = null;
    g.splatCount = 0;
    g.sample = null;
  }

  private disposeGalaxy(g: GalaxyVisual): void {
    this.dropSplats(g);
    g.glow.removeFromParent();
    g.glowMat.dispose();
    g.splatMat.dispose();
    g.label.remove();
  }

  private ensureSplats(g: GalaxyVisual, count: number): void {
    if (!this.provider || g.splatCount >= count * 0.9 || g.pending >= count * 0.9) return;
    g.pending = count;
    const serial = ++this.sampleSerial;
    void this.provider.sample(g.model.id, count).then((s) => {
      if (this.disposed || !this.galaxies.has(g.model.id) || g.pending !== count) return;
      g.pending = 0;
      if (!s || !s.count) return;
      this.dropSplats(g);
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(s.positions, 3));
      geo.setAttribute('color', new THREE.BufferAttribute(s.colors, 3));
      let sum = 0;
      for (let i = 0; i < s.count; i++) sum += s.brightness[i]!;
      const mean = sum / s.count || 1;
      const w = new Float32Array(s.count);
      for (let i = 0; i < s.count; i++) w[i] = Math.min(6, Math.max(0.15, s.brightness[i]! / mean));
      geo.setAttribute('aWeight', new THREE.BufferAttribute(w, 1));
      const pts = new THREE.Points(geo, g.splatMat);
      pts.frustumCulled = false;
      pts.renderOrder = -1;
      if (s.frame === 'galaxy') pts.quaternion.copy(g.rotation);
      this.scene.add(pts);
      g.splats = pts;
      g.splatCount = s.count;
      g.sample = s;
      const cell = (g.model.radiusPc * 2.2) / Math.sqrt(s.count);
      g.splatMat.uniforms.uSplat!.value = cell;
      g.splatMat.uniforms.uNear!.value = cell;
      g.splatMat.uniforms.uGain!.value = THREE.MathUtils.clamp(2600 / s.count, 0.02, 0.35) * galaxyIntensity(g.model);
      this.lastActivity = performance.now();
      void serial;
    });
  }

  private rebuildObserved(): void {
    const obs = this.provider?.observed ?? [];
    const key = obs.length + ':' + (obs[0]?.id ?? '');
    if (key === this.obsKey) return;
    this.obsKey = key;
    const n = obs.length;
    const pos = new Float32Array(n * 3);
    const col = new Float32Array(n * 3);
    const lum = new Float32Array(n);
    const flag = new Float32Array(n);
    obs.forEach((s, i) => {
      // Positions relative to the Sun (where nearly all observed stars are), anchored at the Sun's position.
      const sun = this.provider!.sunPc;
      pos[i * 3] = s.positionPc[0] - sun[0];
      pos[i * 3 + 1] = s.positionPc[1] - sun[1];
      pos[i * 3 + 2] = s.positionPc[2] - sun[2];
      const c = starColor(s.teffK);
      col.set(c, i * 3);
      lum[i] = s.luminositySun;
      flag[i] = 1;
    });
    const geo = this.obsPoints.geometry;
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    geo.setAttribute('aLum', new THREE.BufferAttribute(lum, 1));
    geo.setAttribute('aFlag', new THREE.BufferAttribute(flag, 1));
    geo.computeBoundingSphere();
    for (const el of this.obsLabels.values()) el.remove();
    this.obsLabels.clear();
    for (const s of obs) {
      const el = this.makeLabel('uni-lbl observed');
      el.dataset.star = s.id;
      (el.querySelector('.uni-text') as HTMLElement).textContent = s.name.en;
      this.obsLabels.set(s.id, el);
    }
  }

  /** Navigation regions: labels at overview scale; galaxy labels follow their region's activity. */
  setRegions(regions: MapRegion[]): void {
    for (const el of this.regionLabels.values()) el.remove();
    this.regionLabels.clear();
    this.regions = regions;
    this.galaxyRegion = new Map();
    // Innermost region wins (deeper regions are assigned last).
    for (const r of [...regions].sort((a, b) => a.depth - b.depth)) for (const g of r.members) this.galaxyRegion.set(g, r.id);
    for (const r of regions) {
      const el = this.makeLabel('uni-lbl region');
      el.dataset.region = r.id;
      this.regionLabels.set(r.id, el);
    }
    this.lastActivity = performance.now();
  }

  private regionNames: Record<string, string> = {};
  private formatDistance: ((pc: number) => string) | null = null;

  setRegionNames(names: Record<string, string>, formatDistance?: (pc: number) => string): void {
    this.regionNames = { ...names };
    if (formatDistance) this.formatDistance = formatDistance;
    for (const [id, el] of this.regionLabels) {
      const t = names[id];
      if (t) (el.querySelector('.uni-text') as HTMLElement).textContent = t;
    }
    this.lastActivity = performance.now();
  }

  /** Label texts follow the interface language. */
  setNames(galaxyNames: Record<string, string>, starNames: Record<string, string>, sunName: string): void {
    for (const g of this.galaxies.values()) {
      const t = galaxyNames[g.model.id];
      if (t) (g.label.querySelector('.uni-text') as HTMLElement).textContent = t;
    }
    for (const [id, el] of this.obsLabels) {
      const t = starNames[id];
      if (t) (el.querySelector('.uni-text') as HTMLElement).textContent = t;
    }
    (this.sunLabel.querySelector('.uni-text') as HTMLElement).textContent = sunName;
    this.lastActivity = performance.now();
  }

  // ---- per-frame -----------------------------------------------------------------------------------------------------

  private updateFlight(now: number): void {
    const f = this.flight;
    if (!f) return;
    const k = Math.min(1, (now - f.t0) / f.dur);
    const e = ease(k);
    const pos: Vec3 = [f.from[0] + (f.to[0] - f.from[0]) * e, f.from[1] + (f.to[1] - f.from[1]) * e, f.from[2] + (f.to[2] - f.from[2]) * e];
    const l0 = Math.log(f.d0);
    const l1 = Math.log(f.d1);
    const lc = Math.log(f.cruise);
    const base = l0 + (l1 - l0) * e;
    const bump = Math.sin(Math.PI * k) * Math.max(0, lc - Math.max(l0, l1));
    const dist = Math.exp(base + bump);
    const off = this.camera.position.clone().sub(this.controls.target);
    const dir = off.lengthSq() > 0 ? off.normalize() : new THREE.Vector3(0, 0.5, 0.86);
    this.origin = pos;
    this.controls.target.set(0, 0, 0);
    this.camera.position.copy(dir.multiplyScalar(dist));
    const remaining = len3(sub3(f.to, pos));
    const dt = 1 / 60;
    const k2 = Math.min(1, k + dt / (f.dur / 1000));
    const e2 = ease(k2);
    const total = len3(sub3(f.to, f.from));
    const v = (total * (e2 - e)) / dt;
    f.onProgress?.({ t: k, remainingPc: remaining, speedPcPerS: v, speedC: v / C_PC_PER_S });
    if (k >= 1) {
      this.flight = null;
      f.resolve('arrived');
    }
  }

  private updateLod(now: number): void {
    const p = this.provider;
    if (!p) return;
    const target = this.cameraState();
    // Which galaxy are we in or nearest to (relative to its size)?
    let best: GalaxyVisual | null = null;
    let bestRel = Infinity;
    const camPc: Vec3 = [this.origin[0] + this.camera.position.x, this.origin[1] + this.camera.position.y, this.origin[2] + this.camera.position.z];
    for (const g of this.galaxies.values()) {
      const rel = len3(sub3(camPc, g.centre)) / g.model.radiusPc;
      if (rel < bestRel) {
        bestRel = rel;
        best = g;
      }
    }
    this.currentGalaxy = best && bestRel < 6 ? best.model.id : null;
    const big = BIG_SAMPLE[this.options.quality];
    const small = Math.min(24000, Math.max(3000, Math.round(big / 12)));
    // Bounded: the current galaxy gets the big sample; at most ten others (largest on screen) get small ones; samples of
    // galaxies that shrink to a few pixels are released, so a crowded cluster view never holds dozens of samples.
    const neighbours = [...this.galaxies.values()]
      .filter((g) => g !== best && g.screenRadius > 40 && len3(sub3(camPc, g.centre)) / g.model.radiusPc < 60)
      .sort((a, b) => b.screenRadius - a.screenRadius)
      .slice(0, 10);
    for (const g of this.galaxies.values()) {
      const rel = len3(sub3(camPc, g.centre)) / g.model.radiusPc;
      if (g === best && rel < 6) this.ensureSplats(g, big);
      else if (neighbours.includes(g)) this.ensureSplats(g, small);
      else if (g.splats && g.screenRadius < 12) this.dropSplats(g);
    }
    // Real stars near the target when the view is small enough to tell them apart. The sphere is sized from the model's
    // density so the expected count stays near the limit (a dense bulge gets a small sphere, the halo a big one).
    const viewW = this.viewWidth(target.distancePc);
    if (viewW < 300 && this.currentGalaxy) {
      const limit = NEAR_STARS[this.options.quality];
      const rho = Math.max(p.density(this.currentGalaxy, target.targetPc), 1e-6);
      const rDensity = Math.cbrt((3 * limit) / (4 * Math.PI * rho));
      const radius = THREE.MathUtils.clamp(Math.min(Math.max(viewW * 0.7, 8), rDensity), 0.3, 30);
      const q = this.nearQuery;
      const moved = q ? len3(sub3(target.targetPc, q.centre)) : Infinity;
      if (!q || moved > q.radius * 0.35 || radius > q.radius * 1.8 || radius < q.radius * 0.4) {
        if (!q || now - q.t > 220) {
          const res = p.near(this.currentGalaxy, target.targetPc, radius, NEAR_STARS[this.options.quality]);
          this.setNear(target.targetPc, radius, res, now);
        }
      }
    } else if (this.nearQuery) {
      this.setNear(target.targetPc, 0, null, now);
      this.nearQuery = null;
    }
  }

  private setNear(centre: Vec3, radius: number, res: NearResult | null, now: number): void {
    if (this.nearPoints) {
      this.nearPoints.geometry.dispose();
      this.nearPoints.removeFromParent();
      this.nearPoints = null;
    }
    this.nearStars = [];
    if (!res) return;
    const stars = res.stars.filter((s) => s.provenance === 'procedural');
    this.nearStars = stars;
    this.nearQuery = { centre: [...centre] as Vec3, radius, complete: !res.truncated, t: now };
    this.nearTotal = res.modelCountInRadius;
    const n = stars.length;
    const pos = new Float32Array(n * 3);
    const col = new Float32Array(n * 3);
    const lum = new Float32Array(n);
    const flag = new Float32Array(n);
    stars.forEach((s, i) => {
      pos[i * 3] = s.positionPc[0] - centre[0];
      pos[i * 3 + 1] = s.positionPc[1] - centre[1];
      pos[i * 3 + 2] = s.positionPc[2] - centre[2];
      col.set(starColor(s.teffK), i * 3);
      lum[i] = s.luminositySun;
    });
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    geo.setAttribute('aLum', new THREE.BufferAttribute(lum, 1));
    geo.setAttribute('aFlag', new THREE.BufferAttribute(flag, 1));
    const pts = new THREE.Points(geo, this.nearMat);
    pts.frustumCulled = false;
    pts.userData.anchor = [...centre];
    this.nearPoints = pts;
    this.scene.add(pts);
  }

  private viewWidth(distancePc: number): number {
    return 2 * distancePc * Math.tan(THREE.MathUtils.degToRad(this.camera.fov / 2)) * this.camera.aspect;
  }

  private place3(obj: THREE.Object3D, pc: Vec3): void {
    obj.position.set(pc[0] - this.origin[0], pc[1] - this.origin[1], pc[2] - this.origin[2]);
  }

  private updateScene(): void {
    const h = Math.max(1, this.container.clientHeight);
    const focal = (h / (2 * Math.tan(THREE.MathUtils.degToRad(this.camera.fov / 2)))) * this.renderer.getPixelRatio();
    const camLocal = this.camera.position;
    for (const g of this.galaxies.values()) {
      this.place3(g.glow, g.centre);
      if (g.splats) this.place3(g.splats, g.centre);
      g.splatMat.uniforms.uFocal!.value = focal;
      // From inside a galaxy its sample stars are seen as stars (small points), not as patches of the disk.
      const inside = this.tmp.copy(g.glow.position).sub(camLocal).length() < g.model.radiusPc * 1.1;
      g.splatMat.uniforms.uMaxPx!.value = (inside ? 2.6 : 26) * this.renderer.getPixelRatio();
      // The glow is the far view; it fades as the camera enters and the splats take over.
      const d = this.tmp.copy(g.glow.position).sub(camLocal).length();
      const rel = d / g.model.radiusPc;
      const fadeIn = THREE.MathUtils.smoothstep(rel, 0.6, 2.5);
      g.glowMat.uniforms.uIntensity!.value = galaxyIntensity(g.model) * 0.3 * (g.splats ? 0.1 + 0.9 * fadeIn : 1);
    }
    if (this.provider) {
      this.place3(this.obsPoints, this.provider.sunPc);
    }
    if (this.nearPoints) this.place3(this.nearPoints, this.nearPoints.userData.anchor as Vec3);
  }

  private updateLabels(): void {
    const w = this.container.clientWidth;
    const h = this.container.clientHeight;
    const project = (local: THREE.Vector3): { x: number; y: number; ok: boolean } => {
      const p = this.tmp.copy(local).project(this.camera);
      const ok = p.z > -1 && p.z < 1;
      return { x: (p.x * 0.5 + 0.5) * w, y: (-p.y * 0.5 + 0.5) * h, ok };
    };
    const showAt = (el: HTMLElement, x: number, y: number, show: boolean) => {
      if (!show) {
        if (el.style.display !== 'none') el.style.display = 'none';
        return;
      }
      el.style.display = '';
      el.style.transform = `translate3d(${x.toFixed(1)}px, ${y.toFixed(1)}px, 0)`;
    };
    const focal = h / (2 * Math.tan(THREE.MathUtils.degToRad(this.camera.fov / 2)));
    // Galaxy labels: by priority (selected, current, the big neighbours, then size); overlapping ones are skipped.
    const galaxyPlaced: { x0: number; y0: number; x1: number; y1: number }[] = [];
    const prio = (g: GalaxyVisual): number => {
      if (this.selection?.kind === 'galaxy' && this.selection.galaxyId === g.model.id) return 1e9;
      if (g.model.id === this.currentGalaxy) return 1e8;
      const featured = FEATURED_GALAXIES.indexOf(g.model.id);
      if (featured >= 0) return 1e7 - featured;
      return Math.log10(Math.max(g.model.modelStarCount, 1));
    };
    // Regions: which ones the camera is in (galaxy labels depend on it).
    const camPc: Vec3 = [this.origin[0] + this.camera.position.x, this.origin[1] + this.camera.position.y, this.origin[2] + this.camera.position.z];
    const activeRegions = new Set<string>();
    const regionById = new Map(this.regions.map((r) => [r.id, r] as const));
    // Labels stay in context: things much farther away than the current view scale are not named over a close-up.
    const contextReach = this.viewWidth(this.camera.position.length()) * 12;
    // "In" a region = within the distance its framing uses (about 2.7 radii) plus a margin.
    const insideRegion = (r: MapRegion) => len3(sub3(camPc, r.centrePc)) < r.radiusPc * 3.4;
    for (const r of this.regions) if (insideRegion(r)) activeRegions.add(r.id);
    const labelPlaced: { x0: number; y0: number; x1: number; y1: number }[] = [];
    const order = [...this.galaxies.values()].sort((a, b) => prio(b) - prio(a));
    for (const g of order) {
      const s = project(g.glow.position);
      const d = g.glow.position.distanceTo(this.camera.position);
      g.screenRadius = (g.model.radiusPc * focal) / Math.max(d, 1e-9);
      g.screen.set(s.x, s.y);
      g.onScreen = s.ok && s.x > -200 && s.x < w + 200 && s.y > -200 && s.y < h + 200;
      const inside = d < g.model.radiusPc * 1.2;
      // At stellar scales other galaxies are only directions in the sky; their labels would read as nearby objects.
      const stellarScale = this.viewWidth(this.camera.position.length()) < 2000;
      // A galaxy is named when its region is active (camera in or near it), when it is big on screen, or when chosen.
      const region = this.galaxyRegion.get(g.model.id);
      // Navigation-only lists (low priority) span the whole local volume: being "in" them names nothing by itself.
      const regionActive = !region || this.regions.length === 0 || (activeRegions.has(region) && (regionById.get(region)?.priority ?? 50) >= 20);
      const featured = FEATURED_GALAXIES.includes(g.model.id) && g.screenRadius > 3;
      const inReach = d < contextReach || this.selection?.kind === 'galaxy' && this.selection.galaxyId === g.model.id;
      const named = (regionActive || featured || g.screenRadius > 14 || g.model.id === this.currentGalaxy) && inReach;
      g.label.classList.toggle('tiny', g.screenRadius < 3.5);
      let show = g.onScreen && !inside && g.screenRadius < w * 0.6 && !stellarScale && named;
      const selected = this.selection?.kind === 'galaxy' && this.selection.galaxyId === g.model.id;
      if (show) {
        const tw = 16 + (g.label.textContent?.length ?? 6) * 7.4;
        const rect = { x0: s.x - tw / 2, y0: s.y + 4, x1: s.x + tw / 2, y1: s.y + 24 };
        const overlaps = galaxyPlaced.some((r) => rect.x0 < r.x1 && rect.x1 > r.x0 && rect.y0 < r.y1 && rect.y1 > r.y0);
        if (overlaps && !selected) show = false;
        else {
          galaxyPlaced.push(rect);
          labelPlaced.push(rect);
        }
      }
      // A far galaxy keeps its soft dot even when its name is left out (crowding, inactive region).
      const dot = g.onScreen && !inside && !stellarScale && g.screenRadius < 3.5;
      showAt(g.label, s.x, s.y, show || dot);
      g.label.classList.toggle('hide-text', !show);
      g.label.classList.toggle('selected', selected);
    }
    // Region labels after the galaxies: a far region never crowds a nearer galaxy's name (e.g. the Fornax Cluster,
    // 19 Mpc away, projected onto the Milky Way's Fornax dwarf), and a far region says how far it is.
    for (const r of [...this.regions].sort((a, b) => a.depth - b.depth || b.priority - a.priority)) {
      const el = this.regionLabels.get(r.id);
      if (!el) continue;
      const local = new THREE.Vector3(r.centrePc[0] - this.origin[0], r.centrePc[1] - this.origin[1], r.centrePc[2] - this.origin[2]);
      const d = local.distanceTo(this.camera.position);
      const sr = (r.radiusPc * focal) / Math.max(d, 1e-9);
      const parent = r.parent ? regionById.get(r.parent) : undefined;
      const parentOk = !parent || parent.depth === 0 || activeRegions.has(parent.id);
      const selected = this.selection?.kind === 'region' && this.selection.regionId === r.id;
      const visible = parentOk && !activeRegions.has(r.id) && sr < Math.min(w, h) * 0.45 && (d < contextReach || selected);
      const far = activeRegions.size > 0 && d > r.radiusPc * 6;
      const name = this.regionNames[r.id] ?? r.id;
      const text = far && this.formatDistance ? `${name} · ${this.formatDistance(d)}` : name;
      const textEl = el.querySelector('.uni-text') as HTMLElement;
      if (textEl.textContent !== text) textEl.textContent = text;
      const s = project(local);
      let show = visible && s.ok;
      if (show) {
        const tw = 22 + text.length * 8;
        const rect = { x0: s.x - tw / 2 - 24, y0: s.y - 22, x1: s.x + tw / 2 + 24, y1: s.y + 22 };
        if (labelPlaced.some((q) => rect.x0 < q.x1 && rect.x1 > q.x0 && rect.y0 < q.y1 && rect.y1 > q.y0) && !selected) show = false;
        else labelPlaced.push(rect);
      }
      showAt(el, s.x, s.y, show);
      el.classList.toggle('selected', selected);
    }
    if (this.provider) {
      const sunLocal = this.tmp.set(this.provider.sunPc[0] - this.origin[0], this.provider.sunPc[1] - this.origin[1], this.provider.sunPc[2] - this.origin[2]).clone();
      const s = project(sunLocal);
      const dSun = sunLocal.distanceTo(this.camera.position);
      showAt(this.sunLabel, s.x, s.y, s.ok && dSun < 40000 && dSun > 1e-6);
      // Observed star labels: only when the view is near the solar neighbourhood; brightest first.
      const viewW = this.viewWidth(this.camera.position.length());
      const placed: { x0: number; y0: number; x1: number; y1: number }[] = [];
      const obs = this.provider.observed;
      const order = [...obs].sort((a, b) => b.luminositySun - a.luminositySun);
      for (const st of order) {
        const el = this.obsLabels.get(st.id);
        if (!el) continue;
        const local = new THREE.Vector3(st.positionPc[0] - this.origin[0], st.positionPc[1] - this.origin[1], st.positionPc[2] - this.origin[2]);
        const pr = project(local);
        const isSel = this.selection?.kind === 'star' && this.selection.star.id === st.id;
        let show = pr.ok && viewW < 3000 && pr.x > -20 && pr.x < w + 20 && pr.y > -20 && pr.y < h + 20;
        if (show && !isSel) {
          const tw = 20 + (el.textContent?.length ?? 4) * 7.6;
          const rect = { x0: pr.x - 6, y0: pr.y - 11, x1: pr.x + 8 + tw, y1: pr.y + 11 };
          if (placed.some((r) => rect.x0 < r.x1 && rect.x1 > r.x0 && rect.y0 < r.y1 && rect.y1 > r.y0) || placed.length > 40) show = false;
          else placed.push(rect);
        }
        showAt(el, pr.x, pr.y, show || (isSel && pr.ok));
        el.classList.toggle('selected', isSel);
      }
    }
    // Selection marker for model stars and map points.
    const sel = this.selection;
    let selPos: Vec3 | null = null;
    let selName = '';
    if (sel?.kind === 'star' && sel.star.provenance === 'procedural') {
      selPos = sel.star.positionPc;
      selName = sel.star.name.en;
    } else if (sel?.kind === 'point') selPos = sel.positionPc;
    if (selPos) {
      const pr = project(new THREE.Vector3(selPos[0] - this.origin[0], selPos[1] - this.origin[1], selPos[2] - this.origin[2]));
      (this.selLabel.querySelector('.uni-text') as HTMLElement).textContent = sel?.kind === 'star' ? (this.selLabel.dataset.name ?? selName) : '';
      showAt(this.selLabel, pr.x, pr.y, pr.ok);
    } else showAt(this.selLabel, 0, 0, false);
  }

  /** The selected model star's label text (language-aware, set by the page). */
  setSelectionName(name: string): void {
    this.selLabel.dataset.name = name;
  }

  private emitState(now: number): void {
    if (now - this.lastState < 250) return;
    this.lastState = now;
    const st = this.cameraState();
    const g = this.currentGalaxy ? this.galaxies.get(this.currentGalaxy) : null;
    const camPc: Vec3 = [this.origin[0] + this.camera.position.x, this.origin[1] + this.camera.position.y, this.origin[2] + this.camera.position.z];
    this.events.onState?.({
      targetPc: st.targetPc,
      distancePc: st.distancePc,
      galaxyId: this.currentGalaxy,
      inside: !!g && len3(sub3(camPc, g.centre)) < g.model.radiusPc * 1.3,
      viewWidthPc: this.viewWidth(st.distancePc),
      sample: g && g.sample ? { galaxyId: g.model.id, shown: g.sample.count, represents: g.sample.represents } : null,
      near: this.nearQuery ? { radiusPc: this.nearQuery.radius, shown: this.nearStars.length, total: this.nearTotal, complete: this.nearQuery.complete } : null,
    });
  }

  private loop = (): void => {
    if (!this.running) return;
    this.raf = requestAnimationFrame(this.loop);
    if (!this.visible || document.hidden) return;
    const now = performance.now();
    const active = this.flight !== null || now - this.lastActivity < 500;
    if (now - this.lastRender < (active ? 0 : 120)) return;
    this.lastRender = now;
    const dt = this.clock.getDelta();
    this.updateFlight(now);
    this.controls.update(dt);
    this.camera.updateMatrixWorld();
    this.updateLod(now);
    this.updateScene();
    this.skyCamera.quaternion.copy(this.camera.quaternion);
    this.updateLabels();
    this.composer.render(dt);
    this.emitState(now);
    void this.disposed;
  };

  // ---- picking -------------------------------------------------------------------------------------------------------

  private pick(x: number, y: number): Selection | null {
    const w = this.container.clientWidth;
    const h = this.container.clientHeight;
    let best: Selection | null = null;
    let bestD = 14;
    const v = new THREE.Vector3();
    const test = (local: THREE.Vector3, sel: Selection, reach: number) => {
      v.copy(local).project(this.camera);
      if (v.z < -1 || v.z > 1) return;
      const sx = (v.x * 0.5 + 0.5) * w;
      const sy = (-v.y * 0.5 + 0.5) * h;
      const d = Math.hypot(sx - x, sy - y);
      if (d < Math.min(bestD, reach)) {
        bestD = d;
        best = sel;
      }
    };
    // Stars first (they are the precise targets), then galaxies by label/centre.
    if (this.nearPoints) {
      const a = this.nearPoints.userData.anchor as Vec3;
      for (const s of this.nearStars) {
        test(new THREE.Vector3(s.positionPc[0] - this.origin[0], s.positionPc[1] - this.origin[1], s.positionPc[2] - this.origin[2]), { kind: 'star', star: s }, 14);
      }
      void a;
    }
    const viewW = this.viewWidth(this.camera.position.length());
    if (this.provider && viewW < 3000) {
      for (const s of this.provider.observed) {
        test(new THREE.Vector3(s.positionPc[0] - this.origin[0], s.positionPc[1] - this.origin[1], s.positionPc[2] - this.origin[2]), { kind: 'star', star: s }, 16);
      }
    }
    if (best) return best;
    // Sample points are selectable only when they are exact model stars: resolve the nearest drawn one to its own id
    // and accept it only if the model puts that star exactly where it is drawn.
    if (this.currentGalaxy && this.provider) {
      const g = this.galaxies.get(this.currentGalaxy)!;
      if (g.splats && g.sample && g.sample.ids) {
        const s = g.sample;
        const m = new THREE.Matrix4().multiplyMatrices(this.camera.projectionMatrix, this.camera.matrixWorldInverse).multiply(g.splats.matrixWorld);
        const e = m.elements;
        let bi = -1;
        let bd = 10;
        for (let i = 0; i < s.count; i++) {
          const x0 = s.positions[i * 3]!;
          const y0 = s.positions[i * 3 + 1]!;
          const z0 = s.positions[i * 3 + 2]!;
          const cw = e[3]! * x0 + e[7]! * y0 + e[11]! * z0 + e[15]!;
          if (cw <= 0) continue;
          const cx = (e[0]! * x0 + e[4]! * y0 + e[8]! * z0 + e[12]!) / cw;
          const cy = (e[1]! * x0 + e[5]! * y0 + e[9]! * z0 + e[13]!) / cw;
          const sx = (cx * 0.5 + 0.5) * w;
          const sy = (-cy * 0.5 + 0.5) * h;
          const d = Math.abs(sx - x) + Math.abs(sy - y);
          if (d < bd) {
            bd = d;
            bi = i;
          }
        }
        if (bi >= 0) {
          const star = this.provider.starById(g.model.id, s.ids![bi]!);
          if (star) {
            const local = new THREE.Vector3(s.positions[bi * 3]!, s.positions[bi * 3 + 1]!, s.positions[bi * 3 + 2]!);
            if (s.frame === 'galaxy') local.applyQuaternion(g.rotation);
            const drawn: Vec3 = [g.centre[0] + local.x, g.centre[1] + local.y, g.centre[2] + local.z];
            const err = len3(sub3(drawn, star.positionPc));
            const tol = Math.max(1e-3, len3(sub3(star.positionPc, g.centre)) * 2e-6);
            if (err <= tol) return { kind: 'star', star };
          }
        }
      }
    }
    for (const g of this.galaxies.values()) {
      if (!g.onScreen) continue;
      const d = Math.hypot(g.screen.x - x, g.screen.y - y);
      const reach = Math.max(18, Math.min(g.screenRadius * 0.6, 160));
      const inside = g.glow.position.distanceTo(this.camera.position) < g.model.radiusPc * 1.2;
      if (!inside && d < reach) return { kind: 'galaxy', galaxyId: g.model.id };
    }
    // Inside a galaxy: a click on its plane picks a region to fly to.
    if (this.currentGalaxy) {
      const g = this.galaxies.get(this.currentGalaxy)!;
      const normal = new THREE.Vector3(...g.model.normal).normalize();
      const ndc = new THREE.Vector2((x / w) * 2 - 1, -(y / h) * 2 + 1);
      const ray = new THREE.Raycaster();
      ray.setFromCamera(ndc, this.camera);
      const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(normal, g.glow.position);
      const hit = ray.ray.intersectPlane(plane, new THREE.Vector3());
      if (hit && hit.distanceTo(g.glow.position) < g.model.radiusPc) {
        return { kind: 'point', galaxyId: g.model.id, positionPc: [hit.x + this.origin[0], hit.y + this.origin[1], hit.z + this.origin[2]] };
      }
    }
    return null;
  }

  private localXY(e: MouseEvent): [number, number] {
    const r = this.container.getBoundingClientRect();
    return [e.clientX - r.left, e.clientY - r.top];
  }

  private onPointerDown = (e: PointerEvent): void => {
    this.pointerDown = { x: e.clientX, y: e.clientY, t: performance.now() };
  };

  private onPointerUp = (e: PointerEvent): void => {
    if (!this.pointerDown) return;
    const moved = Math.hypot(e.clientX - this.pointerDown.x, e.clientY - this.pointerDown.y);
    const quick = performance.now() - this.pointerDown.t < 600;
    this.pointerDown = null;
    if (moved > 6 || !quick || e.button !== 0) return;
    const [x, y] = this.localXY(e);
    const sel = this.pick(x, y);
    this.events.onSelect?.(sel);
    if (e.pointerType === 'touch') {
      const now = performance.now();
      if (sel && now - this.lastTap < 320) this.events.onActivate?.(sel);
      this.lastTap = now;
    }
  };

  private onDblClick = (e: MouseEvent): void => {
    const [x, y] = this.localXY(e);
    const sel = this.pick(x, y);
    if (sel) this.events.onActivate?.(sel);
  };

  private onContextMenu = (e: MouseEvent): void => {
    e.preventDefault();
  };

  private labelSel(e: MouseEvent): Selection | null {
    const el = (e.target as HTMLElement).closest('.uni-lbl') as HTMLElement | null;
    if (!el || !this.provider) return null;
    if (el.dataset.galaxy) return { kind: 'galaxy', galaxyId: el.dataset.galaxy };
    if (el.dataset.region) return { kind: 'region', regionId: el.dataset.region };
    if (el.dataset.star) {
      const s = this.provider.observed.find((x) => x.id === el.dataset.star);
      return s ? { kind: 'star', star: s } : null;
    }
    return null;
  }

  private onLabelClick = (e: MouseEvent): void => {
    const sel = this.labelSel(e);
    if (sel) this.events.onSelect?.(sel);
  };

  private onLabelDblClick = (e: MouseEvent): void => {
    const sel = this.labelSel(e);
    if (sel) this.events.onActivate?.(sel);
  };
}

export const UNIVERSE_CONST = { C_PC_PER_S, LY_PER_PC };
