const FEATURED = ['milky_way', 'm31', 'lmc', 'smc', 'm33'];
const STAR_VIEW_PC = 1.2;
const POINT_VIEW_PC = 22;

interface FlightHud {
  fromName: string;
  toName: string;
  totalPc: number;
  remainingPc: number;
  t: number;
  c: number;
}

function sub(a: Vec3, b: Vec3): Vec3 {
  return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
}
function dist(a: Vec3, b: Vec3): number {
  const d = sub(a, b);
  return Math.hypot(d[0], d[1], d[2]);
}

/** The explanation part of a legend line ("Observed: catalogue measurements" -> "catalogue measurements"). */
function legendText(s: string): string {
  const i = s.indexOf(':');
  return i >= 0 ? s.slice(i + 1).trim() : s;
}

function selectionKey(sel: Selection | null): string | null {
  if (!sel) return null;
  if (sel.kind === 'region') return 'region:' + sel.regionId;
  if (sel.kind === 'galaxy') return 'galaxy:' + sel.galaxyId;
  if (sel.kind === 'star') return sel.star.id;
  return null;
}

function galaxyName(c: Cosmos, id: string, lang: Lang): string {
  return tx(c.galaxyInfo(id)?.name, lang) || tx(c.summary(id)?.name, lang) || id;
}

function regionName(c: Cosmos, id: string, lang: Lang): string {
  return tx(c.region(id)?.info.name, lang) || id;
}

function countText(n: number, t: ReturnType<typeof useT>): string {
  return n === 1 ? t('uni.inCatalogue1') : t('uni.inCatalogue', { n });
}

/** Nearest–farthest member distance from the Sun, the Milky Way itself excluded. */
function distanceRange(c: Cosmos, members: string[], lang: Lang): string {
  let lo = Infinity;
  let hi = 0;
  for (const id of members) {
    if (id === 'milky_way') continue;
    const g = c.summary(id);
    if (!g) continue;
    const d = dist(g.centrePc, c.sunPc);
    lo = Math.min(lo, d);
    hi = Math.max(hi, d);
  }
  if (!Number.isFinite(lo)) return '—';
  const a = formatDistance(lo, lang, false);
  const b = formatDistance(hi, lang, false);
  return a === b ? b : `${a} – ${b}`;
}

const ASSOC_CLASS: Record<string, string> = {
  gravitationally_bound: 'assoc-bound',
  probable_group: 'assoc-group',
  group: 'assoc-group',
  loose_or_uncertain: 'assoc-loose',
  sky_region_only: 'assoc-nav',
  navigation_only: 'assoc-nav',
};

function associationBadge(c: Cosmos, association: string, lang: Lang, t: ReturnType<typeof useT>) {
  const label = tx(c.associationLabels[association]?.label, lang) || t(('uni.assoc.' + association) as Parameters<typeof t>[0]);
  const tip = tx(c.associationLabels[association]?.tip, lang);
  return (
    <span className={'prov-badge ' + (ASSOC_CLASS[association] ?? 'assoc-nav')} title={tip || undefined}>
      <span className="prov-dot" aria-hidden="true" />
      {label}
    </span>
  );
}

function provenanceBadge(kind: 'observed' | 'reconstructed' | 'procedural', t: ReturnType<typeof useT>) {
  const label = kind === 'observed' ? t('uni.legend.observed') : kind === 'reconstructed' ? t('uni.legend.reconstructed') : t('uni.legend.procedural');
  const short = label.split(':')[0];
  return (
    <span className={`prov-badge prov-${kind}`} title={label}>
      <span className="prov-dot" aria-hidden="true" />
      {short}
    </span>
  );
}

// ---- selection card -------------------------------------------------------------------------------------------------

function fieldName(f: string, t: ReturnType<typeof useT>): string {
  const map: Record<string, Parameters<typeof t>[0]> = {
    teffK: 'uni.temperature',
    massSun: 'uni.mass',
    radiusSun: 'uni.radius',
    luminositySun: 'uni.luminosity',
    spectralType: 'uni.spectral',
  };
  return map[f] ? t(map[f]!).toLowerCase() : f;
}

function ObservedSources({ c, recordId }: { c: Cosmos; recordId?: string }) {
  const t = useT();
  if (!recordId || !c.content) return null;
  const k = c.content.KNOWN_STARS.find((s) => s.id === recordId);
  const src = k ? c.content.sourcesOf(k.sources) : [];
  if (!src.length) return null;
  return (
    <div className="sources">
      <p className="eyebrow">{t('uni.sources')}</p>
      <ul>
        {src.slice(0, 5).map((s) => (
          <li key={s.id}>
            {s.url ? (
              <a href={s.url} target="_blank" rel="noreferrer">
                {s.title || s.id}
                <Icon name="external" size={13} />
              </a>
            ) : (
              s.title || s.id
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

function StarCard({ c, star, onFly, onEnter, flying }: { c: Cosmos; star: MapStar; onFly: () => void; onEnter: (hypothetical: boolean) => void; flying: boolean }) {
  const t = useT();
  const lang = useLang();
  const reduced = useSetting('reducedMotion');
  const entering = useStore(universeStore, (s) => s.entering);
  const dSun = dist(star.positionPc, c.sunPc);
  const sceneId = sceneIdOf(star);
  const procedural = star.provenance === 'procedural';
  const m = star.raw as Partial<Omit<CoreModelStar, 'provenance' | 'address' | 'name'>> & Partial<Omit<CoreObservedStar, 'provenance' | 'name'>>;
  const mass = m.massSun;
  const radius = m.radiusSun;
  const lumi = m.luminositySun;
  const pop = m.component?.kind;
  const canObservedSystem = !procedural && !sceneId && !!c.core.generateSystemForObservedStar;
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(star.id);
      notify(t('uni.copied'), 'success');
    } catch {
      notify(star.id, 'info');
    }
  };
  return (
    <>
      <div className="uv-card-head">
        <p className="eyebrow">{procedural ? t('uni.designation') : t('uni.observedHost')}</p>
        <h2 className="uv-card-title">{tx(star.name, lang)}</h2>
        <div className="uv-badges">
          {provenanceBadge(procedural ? 'procedural' : 'observed', t)}
          <span className="uv-galaxy-chip">{t('uni.inGalaxy', { galaxy: galaxyName(c, star.galaxyId, lang) })}</span>
        </div>
      </div>
      <dl className="kv uv-kv">
        <div>
          <dt>{t('uni.distanceSun')}</dt>
          <dd className="num">{formatDistance(dSun, lang)}</dd>
        </div>
        {m.spectralType && (
          <div>
            <dt>{t('uni.spectral')}</dt>
            <dd className="num">{m.spectralType}</dd>
          </div>
        )}
        {Number.isFinite(star.teffK) && star.teffK > 0 && (
          <div>
            <dt>{t('uni.temperature')}</dt>
            <dd className="num">{formatNumber(star.teffK, lang, 4)} K</dd>
          </div>
        )}
        {mass !== undefined && (
          <div>
            <dt>{t('uni.mass')}</dt>
            <dd className="num">{formatNumber(mass, lang, 3)} M☉</dd>
          </div>
        )}
        {radius !== undefined && (
          <div>
            <dt>{t('uni.radius')}</dt>
            <dd className="num">{formatNumber(radius, lang, 3)} R☉</dd>
          </div>
        )}
        {lumi !== undefined && (
          <div>
            <dt>{t('uni.luminosity')}</dt>
            <dd className="num">{formatNumber(lumi, lang, 3)} L☉</dd>
          </div>
        )}
        {pop && (
          <div>
            <dt>{t('uni.population')}</dt>
            <dd>{t(('uni.pop.' + pop) as Parameters<typeof t>[0])}</dd>
          </div>
        )}
        {procedural && m.planetCountHint !== undefined && (
          <div>
            <dt>{t('uni.planets')}</dt>
            <dd className="num">{m.planetCountHint}</dd>
          </div>
        )}
        <div>
          <dt>{t('uni.address')}</dt>
          <dd className="num uv-address">
            <span>{star.id}</span>
            <button type="button" className="icon-btn xs" onClick={() => void copy()} title={t('uni.copyAddress')} aria-label={t('uni.copyAddress')}>
              <Icon name="download" size={14} />
            </button>
          </dd>
        </div>
      </dl>
      {procedural && <p className="faint small">{t('uni.generated')}</p>}
      {!procedural && m.reconstructed && m.reconstructed.length > 0 && (
        <p className="faint small">
          {t('uni.legend.reconstructed').split(':')[0]}: {m.reconstructed.map((f) => fieldName(f, t)).join(', ')}
        </p>
      )}
      {!procedural && <ObservedSources c={c} recordId={(m.record as { id?: string } | undefined)?.id} />}
      <div className="uv-actions">
        <button type="button" className="btn" disabled={flying} onClick={onFly}>
          <Icon name="target" size={17} />
          {reduced ? t('uni.jumpTo') : t('uni.flyTo')}
        </button>
        {sceneId ? (
          <button type="button" className="btn btn-lilac" disabled={entering} onClick={() => onEnter(false)}>
            {entering ? <span className="spinner" /> : <Icon name="sandbox" size={17} />}
            {t('uni.openScene')}
          </button>
        ) : procedural || canObservedSystem ? (
          <button type="button" className="btn btn-lilac" disabled={entering} onClick={() => onEnter(false)}>
            {entering ? <span className="spinner" /> : <Icon name="sandbox" size={17} />}
            {t('uni.enterSystem')}
          </button>
        ) : null}
      </div>
      {(procedural || sceneId || canObservedSystem) && <p className="faint small uv-enter-note">{t('uni.enterNote')}</p>}
      {canObservedSystem && <p className="faint small">{t('uni.enterObservedNote')}</p>}
    </>
  );
}

function DistanceError({ m, c }: { m: { value: number; err?: number | null; errMinus?: number | null; errPlus?: number | null; errKind: string }; c: Cosmos }) {
  const lang = useLang();
  const kind = tx(c.content?.ERR_KIND_LABELS[m.errKind], lang);
  let text = '';
  if (m.err && m.value) text = `± ${formatNumber((m.err / m.value) * 100, lang, 2)} %`;
  else if (m.errMinus && m.errPlus && m.value) text = `+${formatNumber((m.errPlus / m.value) * 100, lang, 2)} / −${formatNumber((m.errMinus / m.value) * 100, lang, 2)} %`;
  if (!text && !kind) return null;
  return (
    <span className="uv-err faint">
      {text}
      {kind ? (text ? ` — ${kind}` : kind) : ''}
    </span>
  );
}

function RegionCard({ c, id, onFly, onGalaxy, onRegion, flying }: { c: Cosmos; id: string; onFly: () => void; onGalaxy: (id: string) => void; onRegion: (id: string) => void; flying: boolean }) {
  const t = useT();
  const lang = useLang();
  const reduced = useSetting('reducedMotion');
  const r = c.region(id);
  const [all, setAll] = useState(false);
  if (!r) return null;
  const info = r.info;
  const parent = info.parent ? c.region(info.parent) : undefined;
  const children = c.regions.filter((x) => x.info.parent === id);
  const members = [...r.allMembers].sort((a, b) => dist(c.summary(a)?.centrePc ?? c.sunPc, c.sunPc) - dist(c.summary(b)?.centrePc ?? c.sunPc, c.sunPc));
  const shown = all ? members : members.slice(0, 12);
  const sources = info.sources && c.content ? c.content.sourcesOf(info.sources) : [];
  return (
    <>
      <div className="uv-card-head">
        <p className="eyebrow">{tx(info.kindLabel, lang) || info.kind}</p>
        <h2 className="uv-card-title">{tx(info.name, lang)}</h2>
        <div className="uv-badges">{associationBadge(c, info.association, lang, t)}</div>
      </div>
      {info.associationNote && <p className="muted small">{tx(info.associationNote, lang)}</p>}
      {info.description && <p className="muted small">{tx(info.description, lang)}</p>}
      <dl className="kv uv-kv">
        <div>
          <dt>{t('uni.galaxies')}</dt>
          <dd className="num">{countText(r.allMembers.length, t)}</dd>
        </div>
        <div>
          <dt>{t('uni.distanceSun')}</dt>
          <dd className="num">{distanceRange(c, r.allMembers, lang)}</dd>
        </div>
        {info.anchorGalaxy && c.summary(info.anchorGalaxy) && (
          <div>
            <dt>{t('uni.anchor')}</dt>
            <dd>
              <button type="button" className="linklike" onClick={() => onGalaxy(info.anchorGalaxy!)}>
                {galaxyName(c, info.anchorGalaxy, lang)}
              </button>
            </dd>
          </div>
        )}
      </dl>
      <p className="faint small">
        {t('uni.countNote')} {t('uni.framingNote')}
      </p>
      {children.length > 0 && (
        <div className="uv-chips">
          <p className="eyebrow">{t('uni.subregions')}</p>
          {children.map((ch) => (
            <button key={ch.info.id} type="button" className="uv-chip" onClick={() => onRegion(ch.info.id)}>
              {tx(ch.info.name, lang)} · {t('uni.inCatalogueShort', { n: ch.allMembers.length })}
            </button>
          ))}
        </div>
      )}
      <ul className="uv-list uv-members">
        {shown.map((gid) => (
          <li key={gid}>
            <button type="button" className="uv-row" onClick={() => onGalaxy(gid)} disabled={flying}>
              <span>{galaxyName(c, gid, lang)}</span>
              <span className="faint small">{gid === 'milky_way' ? t('uni.youAreHere') : formatDistance(dist(c.summary(gid)!.centrePc, c.sunPc), lang, false)}</span>
            </button>
          </li>
        ))}
      </ul>
      {members.length > 12 && (
        <button type="button" className="btn btn-sm btn-ghost" onClick={() => setAll((v) => !v)}>
          {all ? t('common.less') : t('common.more')}
        </button>
      )}
      {sources.length > 0 && (
        <div className="sources">
          <p className="eyebrow">{t('uni.sources')}</p>
          <ul>
            {sources.slice(0, 5).map((s) => (
              <li key={s.id}>
                <a href={s.url} target="_blank" rel="noreferrer">
                  {s.title || s.id}
                  <Icon name="external" size={13} />
                </a>
              </li>
            ))}
          </ul>
        </div>
      )}
      <div className="uv-actions">
        <button type="button" className="btn btn-primary" disabled={flying} onClick={onFly}>
          <Icon name="target" size={17} />
          {reduced ? t('uni.jumpTo') : t('uni.flyRegion')}
        </button>
        {parent && (
          <button type="button" className="btn btn-ghost" disabled={flying} onClick={() => onRegion(parent.info.id)}>
            {t('uni.parentRegion', { name: tx(parent.info.name, lang) })}
          </button>
        )}
      </div>
    </>
  );
}

function GalaxyCard({ c, id, onFly, onOverview, onRegion, flying }: { c: Cosmos; id: string; onFly: () => void; onOverview: () => void; onRegion: (id: string) => void; flying: boolean }) {
  const t = useT();
  const lang = useLang();
  const info = c.galaxyInfo(id);
  const sum = c.summary(id);
  const reduced = useSetting('reducedMotion');
  if (!sum) return null;
  const dSun = dist(sum.centrePc, c.sunPc);
  return (
    <>
      <div className="uv-card-head">
        <p className="eyebrow">
          {tx(info?.kindLabel, lang) || sum.kind}
          {info?.morphology ? ` · ${info.morphology}` : ''}
        </p>
        <h2 className="uv-card-title">{galaxyName(c, id, lang)}</h2>
        <div className="uv-badges">
          {provenanceBadge('reconstructed', t)}
          {c.regionsOf(id)[0] && (
            <button type="button" className="uv-galaxy-chip linklike" onClick={() => onRegion(c.regionsOf(id)[0]!.info.id)}>
              {t('uni.regionOf', { name: tx(c.regionsOf(id)[0]!.info.name, lang) })}
            </button>
          )}
        </div>
      </div>
      {info?.description && <p className="muted small">{tx(info.description, lang)}</p>}
      <dl className="kv uv-kv">
        {id !== 'milky_way' && (
          <div>
            <dt>{t('uni.distanceSun')}</dt>
            <dd className="num">
              {formatDistance(info?.distanceKpc?.value ? info.distanceKpc.value * 1000 : dSun, lang)}
              {info?.distanceKpc && <DistanceError m={info.distanceKpc} c={c} />}
            </dd>
          </div>
        )}
        {info?.diameterKpc !== undefined && (
          <div>
            <dt>{t('uni.diameter')}</dt>
            <dd className="num">{formatDistance(info.diameterKpc * 1000, lang)}</dd>
          </div>
        )}
        {info?.stellarMassMsun !== undefined && (
          <div>
            <dt>{t('uni.stellarMass')}</dt>
            <dd className="num">{formatNumber(info.stellarMassMsun, lang, 2)} M☉</dd>
          </div>
        )}
        <div>
          <dt>{t('uni.modelStars')}</dt>
          <dd className="num">{formatCount(sum.modelStarCount, lang)}</dd>
        </div>
      </dl>
      {info?.shapeNote && <p className="faint small">{tx(info.shapeNote, lang)}</p>}
      {info && info.sources.length > 0 && c.content && (
        <div className="sources">
          <p className="eyebrow">{t('uni.sources')}</p>
          <ul>
            {c.content.sourcesOf(info.sources).slice(0, 5).map((s) => (
              <li key={s.id}>
                {s.url ? (
                  <a href={s.url} target="_blank" rel="noreferrer">
                    {s.title || s.id}
                    <Icon name="external" size={13} />
                  </a>
                ) : (
                  s.title || s.id
                )}
              </li>
            ))}
          </ul>
        </div>
      )}
      <div className="uv-actions">
        <button type="button" className="btn btn-primary" disabled={flying} onClick={onFly}>
          <Icon name="galaxy" size={17} />
          {reduced ? t('uni.jumpTo') : t('uni.enterGalaxy')}
        </button>
        {c.regionsOf(id)[0] ? (
          <button type="button" className="btn btn-ghost" disabled={flying} onClick={() => onRegion(c.regionsOf(id)[0]!.info.id)}>
            {t('uni.parentRegion', { name: tx(c.regionsOf(id)[0]!.info.name, lang) })}
          </button>
        ) : (
          <button type="button" className="btn btn-ghost" disabled={flying} onClick={onOverview}>
            {t('uni.nearbyUniverse')}
          </button>
        )}
      </div>
    </>
  );
}

