function RegionRow({
  c,
  r,
  lang,
  current,
  disabled,
  onRegion,
  onGalaxy,
}: {
  c: Cosmos;
  r: Cosmos['regions'][number];
  lang: Lang;
  current: boolean;
  disabled: boolean;
  onRegion: (id: string) => void;
  onGalaxy: (id: string) => void;
}) {
  const t = useT();
  const [open, setOpen] = useState(false);
  const children = c.regions.filter((x) => x.info.parent === r.info.id);
  const direct = r.info.members.filter((m) => c.summary(m) && !children.some((ch) => ch.allMembers.includes(m)));
  return (
    <div className={'uv-region' + (current ? ' current' : '')}>
      <div className="uv-region-head">
        <button type="button" className="uv-region-main" onClick={() => onRegion(r.info.id)} disabled={disabled}>
          <span className="uv-region-name">
            <span className={'assoc-dot ' + (ASSOC_CLASS[r.info.association] ?? 'assoc-nav')} title={tx(c.associationLabels[r.info.association]?.label, lang) || r.info.association} aria-hidden="true" />
            {tx(r.info.name, lang)}
          </span>
          <span className="uv-region-meta">
            {tx(r.info.kindLabel, lang) || r.info.kind} · {t('uni.inCatalogueShort', { n: r.allMembers.length })} · {distanceRange(c, r.allMembers, lang)}
          </span>
        </button>
        <button type="button" className="icon-btn xs" onClick={() => setOpen((v) => !v)} aria-expanded={open} aria-label={tx(r.info.name, lang)}>
          <Icon name={open ? 'chevronDown' : 'chevronRight'} size={15} />
        </button>
      </div>
      {open && (
        <div className="uv-region-body">
          {children.map((ch) => (
            <RegionRow key={ch.info.id} c={c} r={ch} lang={lang} current={false} disabled={disabled} onRegion={onRegion} onGalaxy={onGalaxy} />
          ))}
          <ul className="uv-list">
            {direct
              .map((id) => ({ id, d: id === 'milky_way' ? 0 : dist(c.summary(id)!.centrePc, c.sunPc) }))
              .sort((a, b) => a.d - b.d)
              .map(({ id, d }) => (
                <li key={id}>
                  <button type="button" className="uv-row" onClick={() => onGalaxy(id)} disabled={disabled}>
                    <span>{galaxyName(c, id, lang)}</span>
                    <span className="faint small">{id === 'milky_way' ? t('uni.youAreHere') : formatDistance(d, lang, false)}</span>
                  </button>
                </li>
              ))}
          </ul>
        </div>
      )}
    </div>
  );
}

// ---- search ---------------------------------------------------------------------------------------------------------

type Hit =
  | { kind: 'region'; id: string; title: string; sub: string }
  | { kind: 'galaxy'; id: string; title: string; sub: string }
  | { kind: 'star'; star: MapStar; title: string; sub: string }
  | { kind: 'unplaced'; known: KnownStar; title: string; sub: string }
  | { kind: 'error'; title: string; sub: string };

function useSearch(c: Cosmos | null, q: string, lang: Lang, t: ReturnType<typeof useT>): Hit[] {
  return useMemo(() => {
    const query = q.trim();
    if (!c || !query) return [];
    const norm = (s: string) => s.toLowerCase().replace(/ё/g, 'е');
    const nq = norm(query);
    const hits: Hit[] = [];
    if (/^(c\d+\.|obs\.)/i.test(query)) {
      const r = c.resolve(query);
      if (r.ok) hits.push({ kind: 'star', star: r.star, title: tx(r.star.name, lang), sub: t('uni.addressHit') + ' · ' + r.star.id });
      else hits.push({ kind: 'error', title: t('uni.addressInvalid', { reason: r.message }), sub: query });
      return hits;
    }
    for (const r of c.regions) {
      const names = [r.info.name.en, r.info.name.ru, r.info.id];
      if (names.some((n) => n && norm(n).includes(nq))) hits.push({ kind: 'region', id: r.info.id, title: tx(r.info.name, lang), sub: `${tx(r.info.kindLabel, lang) || r.info.kind} · ${t('uni.inCatalogueShort', { n: r.allMembers.length })}` });
    }
    for (const g of c.galaxies) {
      const info = c.galaxyInfo(g.id);
      const names = [tx(info?.name, 'en'), tx(info?.name, 'ru'), tx(g.name, 'en'), tx(g.name, 'ru'), g.id, ...(info?.altNames ?? [])];
      if (names.some((n) => n && norm(n).includes(nq))) hits.push({ kind: 'galaxy', id: g.id, title: galaxyName(c, g.id, lang), sub: tx(info?.kindLabel, lang) || g.kind });
    }
    for (const s of c.observed) {
      const raw = s.raw as CoreObservedStar;
      const desig = (raw.record.aliases ?? []).join(' ');
      const hay = norm(`${s.name.en} ${s.name.ru} ${desig}`);
      if (hay.includes(nq)) hits.push({ kind: 'star', star: s, title: tx(s.name, lang), sub: formatDistance(dist(s.positionPc, c.sunPc), lang, false) });
      if (hits.length > 24) break;
    }
    // Catalogue stars the model could not place (no reliable distance): listed, never guessed onto the map.
    if (c.content) {
      const placed = new Set(c.observed.map((s) => s.id));
      for (const k of c.content.KNOWN_STARS) {
        if (placed.has('obs.' + k.id)) continue;
        const hay = norm(`${k.name.en} ${k.name.ru} ${(k.designations ?? []).join(' ')}`);
        if (hay.includes(nq)) hits.push({ kind: 'unplaced', known: k, title: tx(k.name, lang), sub: t('uni.noPosition') });
      }
    }
    return hits.slice(0, 24);
  }, [c, q, lang, t]);
}

// ---- page -------------------------------------------------------------------------------------------------------------

export function UniversePage({ route }: { route: Route }) {
  const t = useT();
  const lang = useLang();
  const quality = useSetting('quality');
  const bloom = useSetting('bloom');
  const reduced = useSetting('reducedMotion');
  const showLabels = useSetting('showLabels');
  const [cosmos, setCosmos] = useState<Cosmos | null>(null);
  const [status, setStatus] = useState<'loading' | 'ready' | 'missing' | 'error' | 'nogl'>(cosmosAvailable() ? 'loading' : 'missing');
  const [errText, setErrText] = useState('');
  const hostRef = useRef<HTMLDivElement>(null);
  const viewRef = useRef<UniverseView | null>(null);
  const [selection, setSelection] = useState<Selection | null>(null);
  const [vstate, setVstate] = useState<UniverseViewState | null>(null);
  const [flight, setFlight] = useState<FlightHud | null>(null);
  const [speed, setSpeed] = useState(1);
  const [placesOpen, setPlacesOpen] = useState(() => window.matchMedia('(min-width: 1101px)').matches);
  const closePlacesOnPhone = useCallback(() => {
    if (window.matchMedia('(max-width: 760px)').matches) setPlacesOpen(false);
  }, []);
  const [legendOpen, setLegendOpen] = useState(false);
  const [q, setQ] = useState('');
  const [searchOpen, setSearchOpen] = useState(false);
  const [starFilter, setStarFilter] = useState('');
  const [unplaced, setUnplaced] = useState<KnownStar | null>(null);
  const [crumbMenu, setCrumbMenu] = useState(false);
  const selfHash = useRef('');
  const skipRef = useRef(false);
  const placedRef = useRef(false);
  const hits = useSearch(cosmos, q, lang, t);

  // The galaxy model and catalogue.
  useEffect(() => {
    if (!cosmosAvailable()) return;
    let live = true;
    loadCosmos()
      .then((c) => {
        if (!live) return;
        setCosmos(c);
        setStatus('ready');
      })
      .catch((e: unknown) => {
        if (!live) return;
        const m = e instanceof Error ? e.message : String(e);
        setStatus(m === 'model-missing' ? 'missing' : 'error');
        setErrText(m);
      });
    return () => {
      live = false;
    };
  }, []);

  // Handlers read the latest state through a ref (the view is created once).
  const handlers = useRef({ select: (_s: Selection | null) => {}, activate: (_s: Selection) => {} });

  // The 3D view: one per page visit (StrictMode-safe: created and disposed by this effect).
  useEffect(() => {
    const el = hostRef.current;
    if (!el) return;
    if (!webglAvailable()) {
      setStatus('nogl');
      return;
    }
    const v = new UniverseView(el, { quality, bloom, reducedMotion: reduced, showLabels }, {
      onSelect: (s) => handlers.current.select(s),
      onActivate: (s) => handlers.current.activate(s),
      onState: (st) => {
        setVstate(st);
        universeStore.set({ view: { targetPc: st.targetPc, distancePc: st.distancePc } });
      },
    });
    viewRef.current = v;
    placedRef.current = false;
    return () => {
      const st = v.cameraState();
      universeStore.set({ view: { targetPc: st.targetPc, distancePc: st.distancePc } });
      v.dispose();
      viewRef.current = null;
    };
    // Options are applied below.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    viewRef.current?.setOptions({ quality, bloom, reducedMotion: reduced, showLabels });
  }, [quality, bloom, reduced, showLabels]);

  // ---- camera helpers ----
  const updateHash = useCallback((path: string) => {
    selfHash.current = '#' + path;
    navigate(path, { replace: true });
  }, []);

  const select = useCallback(
    (s: Selection | null) => {
      setSelection(s);
      if (s) setUnplaced(null);
      viewRef.current?.setSelection(s);
      if (s?.kind === 'star') viewRef.current?.setSelectionName(tx(s.star.name, lang));
      universeStore.set({ selectionId: selectionKey(s) });
      if (s?.kind === 'star') updateHash(`/universe/${encodeURIComponent(s.star.galaxyId)}?star=${encodeURIComponent(s.star.id)}`);
      else if (s?.kind === 'galaxy') updateHash(`/universe/${encodeURIComponent(s.galaxyId)}`);
      else if (s?.kind === 'region') updateHash(`/universe/region/${encodeURIComponent(s.regionId)}`);
    },
    [lang, updateHash],
  );

  const currentName = useCallback((): string => {
    if (!cosmos || !vstate) return t('uni.title');
    if (vstate.galaxyId) return galaxyName(cosmos, vstate.galaxyId, lang);
    const here = cosmos.regions.filter((r) => dist(vstate.targetPc, r.centrePc) < r.radiusPc).sort((a, b) => b.depth - a.depth)[0];
    return here ? tx(here.info.name, lang) : t('uni.nearbyUniverse');
  }, [cosmos, vstate, lang, t]);

  const fly = useCallback(
    async (to: Vec3, distancePc: number, toName: string) => {
      const v = viewRef.current;
      if (!v) return;
      const from = v.cameraState();
      const total = dist(to, from.targetPc);
      if (reduced) {
        v.place(to, distancePc);
        notify(t('uni.flight.jumped', { name: toName }), 'info');
        return;
      }
      skipRef.current = false;
      setFlight({ fromName: currentName(), toName, totalPc: total, remainingPc: total, t: 0, c: 0 });
      let last = 0;
      const res = await v.flyTo(to, distancePc, {
        speed,
        onProgress: (p) => {
          const now = performance.now();
          if (now - last > 100 || p.t >= 1) {
            last = now;
            setFlight((f) => (f ? { ...f, t: p.t, remainingPc: p.remainingPc, c: p.speedC } : f));
          }
        },
      });
      setFlight(null);
      if (skipRef.current) {
        skipRef.current = false;
        v.place(to, distancePc);
        notify(t('uni.flight.jumped', { name: toName }), 'info');
      } else if (res === 'stopped') {
        notify(t('uni.flight.stopped', { d: formatDistance(dist(to, v.cameraState().targetPc), lang) }), 'info');
      }
    },
    [reduced, speed, currentName, t, lang],
  );

  const flyToGalaxy = useCallback(
    (id: string) => {
      if (!cosmos) return;
      const g = cosmos.summary(id);
      if (!g) return;
      select({ kind: 'galaxy', galaxyId: id });
      void fly(g.centrePc, g.radiusPc * 2.3, galaxyName(cosmos, id, lang));
    },
    [cosmos, fly, lang, select],
  );

  const flyToStar = useCallback(
    (s: MapStar) => {
      select({ kind: 'star', star: s });
      void fly(s.positionPc, STAR_VIEW_PC, tx(s.name, lang));
    },
    [fly, lang, select],
  );

  /** Camera distance framing a sphere in the current viewport (portrait phones included). */
  const framed = useCallback(
    (sphere: { centrePc: Vec3; radiusPc: number }): number => {
      const el = hostRef.current;
      const aspect = el && el.clientHeight > 0 ? el.clientWidth / el.clientHeight : 1.6;
      return cosmos ? cosmos.fit(sphere, 50, aspect) : sphere.radiusPc * 3;
    },
    [cosmos],
  );

  const flyToRegion = useCallback(
    (id: string) => {
      if (!cosmos) return;
      const r = cosmos.region(id);
      if (!r) return;
      select({ kind: 'region', regionId: id });
      void fly(r.centrePc, framed(r), regionName(cosmos, id, lang));
    },
    [cosmos, fly, framed, lang, select],
  );

  /** Home: the Local Group (or, without region data, the Milky Way and Andromeda). */
  const homeView = useCallback((): { centrePc: Vec3; distancePc: number } | null => {
    if (!cosmos) return null;
    const lg = cosmos.region('local_group');
    if (lg) return { centrePc: lg.centrePc, distancePc: framed(lg) };
    const mw = cosmos.summary('milky_way');
    const m31 = cosmos.summary('m31');
    if (!mw || !m31) return null;
    const centre: Vec3 = [(mw.centrePc[0] + m31.centrePc[0]) / 2, (mw.centrePc[1] + m31.centrePc[1]) / 2, (mw.centrePc[2] + m31.centrePc[2]) / 2];
    return { centrePc: centre, distancePc: dist(mw.centrePc, m31.centrePc) * 1.25 };
  }, [cosmos, framed]);

  const overview = useCallback(() => {
    const h = homeView();
    if (!h) return;
    select(null);
    updateHash('/universe');
    void fly(h.centrePc, h.distancePc, t('uni.home'));
  }, [homeView, fly, select, t, updateHash]);

  /** The whole catalogue, framed (nearby universe). */
  const nearbyUniverse = useCallback(() => {
    if (!cosmos) return;
    select(null);
    updateHash('/universe/all');
    void fly(cosmos.catalogue.centrePc, framed(cosmos.catalogue), t('uni.nearbyUniverse'));
  }, [cosmos, fly, framed, select, t, updateHash]);

  const goSun = useCallback(() => {
    if (!cosmos) return;
    const sun = cosmos.observed.find((s) => s.id === 'obs.sun');
    if (sun) flyToStar(sun);
    else void fly(cosmos.sunPc, 2, t('uni.sun'));
  }, [cosmos, fly, flyToStar, t]);

  handlers.current.select = (s) => select(s);
  handlers.current.activate = (s) => {
    if (s.kind === 'region') flyToRegion(s.regionId);
    else if (s.kind === 'galaxy') flyToGalaxy(s.galaxyId);
    else if (s.kind === 'star') flyToStar(s.star);
    else if (cosmos) void fly(s.positionPc, POINT_VIEW_PC, galaxyName(cosmos, s.galaxyId, lang));
  };

  // ---- route: initial and external navigation (self-made hash updates are ignored) ----
  useEffect(() => {
    const v = viewRef.current;
    if (!v || !cosmos) return;
    v.setProvider(cosmos.provider);
    const priority = (r: (typeof cosmos.regions)[number]): number => {
      if (r.info.id === 'local_group') return 100;
      if (r.info.kind === 'cluster') return 80 + Math.log10(r.allMembers.length + 1);
      if (r.info.kind === 'navigation_region') return 10 + Math.log10(r.allMembers.length + 1);
      return 50 + Math.log10(r.allMembers.length + 1);
    };
    v.setRegions(
      cosmos.regions.map((r) => ({
        id: r.info.id,
        parent: r.info.parent && cosmos.region(r.info.parent) ? r.info.parent : null,
        centrePc: r.centrePc,
        radiusPc: r.radiusPc,
        members: r.info.members,
        depth: r.depth,
        priority: priority(r),
      })),
    );
    placedRef.current = false;
  }, [cosmos]);

  // Language-aware labels.
  useEffect(() => {
    const v = viewRef.current;
    if (!v || !cosmos) return;
    const gn: Record<string, string> = {};
    for (const g of cosmos.galaxies) gn[g.id] = galaxyName(cosmos, g.id, lang);
    const sn: Record<string, string> = {};
    for (const s of cosmos.observed) sn[s.id] = tx(s.name, lang);
    v.setNames(gn, sn, t('uni.sun'));
    const rn: Record<string, string> = {};
    for (const r of cosmos.regions) rn[r.info.id] = tx(r.info.name, lang);
    v.setRegionNames(rn, (pc) => formatDistance(pc, lang, false));
  }, [cosmos, lang, t, status]);


  useEffect(() => {
    const v = viewRef.current;
    if (!v || !cosmos) return;
    if (placedRef.current && location.hash === selfHash.current) return;
    const galaxyParam = route.rest[0];
    const starParam = route.params.get('star');
    const first = !placedRef.current;
    placedRef.current = true;
    if (starParam) {
      const r = cosmos.resolve(starParam);
      if (r.ok) {
        select({ kind: 'star', star: r.star });
        if (first) v.place(r.star.positionPc, STAR_VIEW_PC);
        else void fly(r.star.positionPc, STAR_VIEW_PC, tx(r.star.name, lang));
        return;
      }
      notify(t('uni.addressInvalid', { reason: r.message }), 'warning');
    }
    // #/universe/region/<id>: a group, cluster or navigation region, framed.
    if (galaxyParam === 'region') {
      const r = cosmos.region(route.rest[1] ?? '');
      if (r) {
        select({ kind: 'region', regionId: r.info.id });
        if (first) v.place(r.centrePc, framed(r), [0.2, -0.5, 0.84]);
        else flyToRegion(r.info.id);
        return;
      }
    }
    // #/universe/all: the whole catalogue (nearby universe).
    if (galaxyParam === 'all') {
      select(null);
      if (first) v.place(cosmos.catalogue.centrePc, framed(cosmos.catalogue), [0.2, -0.5, 0.84]);
      else nearbyUniverse();
      return;
    }
    if (galaxyParam && cosmos.summary(galaxyParam)) {
      const g = cosmos.summary(galaxyParam)!;
      select({ kind: 'galaxy', galaxyId: g.id });
      if (first) v.place(g.centrePc, g.radiusPc * 2.3, [0.15, -0.55, 0.82]);
      else flyToGalaxy(g.id);
      return;
    }
    if (first) {
      const saved = universeStore.get().view;
      if (saved) v.place(saved.targetPc, saved.distancePc);
      else {
        const mw = cosmos.summary('milky_way');
        v.place(mw?.centrePc ?? [0, 0, 0], 1.6e5, [0.3, -0.62, 0.72]);
      }
      const selId = universeStore.get().selectionId;
      if (selId?.startsWith('region:') && cosmos.region(selId.slice(7))) setSelection({ kind: 'region', regionId: selId.slice(7) });
      else if (selId?.startsWith('galaxy:')) setSelection({ kind: 'galaxy', galaxyId: selId.slice(7) });
      else if (selId) {
        const r = cosmos.resolve(selId);
        if (r.ok) {
          setSelection({ kind: 'star', star: r.star });
          v.setSelection({ kind: 'star', star: r.star });
          v.setSelectionName(tx(r.star.name, lang));
        }
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [route.serial, cosmos]);

  // Keys: Escape clears the selection (never while typing); typing in fields never steers the map.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = e.target as HTMLElement | null;
      if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT' || el.isContentEditable)) return;
      if (document.querySelector('[aria-modal="true"]')) return;
      if (e.key === 'Escape') {
        if (viewRef.current?.flying()) viewRef.current.stopFlight();
        else select(null);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [select]);

  const enter = useCallback(
    async (star: MapStar, hypothetical: boolean) => {
      if (!cosmos) return;
      await enterStarSystem(cosmos, star, { hypotheticalPlanets: hypothetical });
    },
    [cosmos],
  );

  // ---- derived UI ----
  const observedSorted = useMemo(() => {
    if (!cosmos) return [];
    const f = starFilter.trim().toLowerCase().replace(/ё/g, 'е');
    return cosmos.observed
      .filter((s) => !f || `${s.name.en} ${s.name.ru}`.toLowerCase().replace(/ё/g, 'е').includes(f))
      .map((s) => ({ s, d: dist(s.positionPc, cosmos.sunPc) }))
      .sort((a, b) => a.d - b.d)
      .slice(0, 80);
  }, [cosmos, starFilter]);

  const sampleText = vstate?.sample ? t('uni.sample', { shown: formatCount(vstate.sample.shown, lang), total: formatCount(vstate.sample.represents, lang) }) : null;
  const nearText = vstate?.near
    ? vstate.near.complete
      ? (vstate.near.total || vstate.near.shown) === 1
        ? t('uni.near1', { r: formatDistance(vstate.near.radiusPc, lang, false) })
        : t('uni.near', { n: formatCount(vstate.near.total || vstate.near.shown, lang), r: formatDistance(vstate.near.radiusPc, lang, false) })
      : t('uni.nearTruncated', { shown: formatCount(vstate.near.shown, lang), n: formatCount(vstate.near.total, lang), r: formatDistance(vstate.near.radiusPc, lang, false) })
    : null;
  const capText = cosmos && vstate?.galaxyId ? t('uni.capacity', { n: formatCount(cosmos.summary(vstate.galaxyId)?.modelStarCount ?? 0, lang) }) : null;
  const flying = flight !== null;

  // Context: the selected thing, else the galaxy the camera is in.
  const ctxGalaxy = selection?.kind === 'galaxy' ? selection.galaxyId : selection?.kind === 'star' ? selection.star.galaxyId : selection?.kind === 'point' ? selection.galaxyId : vstate?.galaxyId ?? null;
  const ctxRegions = useMemo(() => {
    if (!cosmos) return [];
    if (selection?.kind === 'region') {
      const chain = [];
      let r = cosmos.region(selection.regionId);
      const seen = new Set<string>();
      while (r && !seen.has(r.info.id)) {
        seen.add(r.info.id);
        chain.unshift(r);
        r = r.info.parent ? cosmos.region(r.info.parent) : undefined;
      }
      return chain;
    }
    return ctxGalaxy ? [...cosmos.regionsOf(ctxGalaxy)].reverse() : [];
  }, [cosmos, selection, ctxGalaxy]);
  // Breadcrumbs: the full chain, with middle ancestors collapsed into "…" (a menu) when the chain is long.
  const crumbItems: { key: string; label: string; onClick?: () => void }[] = [];
  if (cosmos) {
    crumbItems.push({ key: 'root', label: t('uni.nearbyUniverse'), onClick: nearbyUniverse });
    for (const r of ctxRegions) crumbItems.push({ key: 'r:' + r.info.id, label: tx(r.info.name, lang), onClick: () => flyToRegion(r.info.id) });
    if (ctxGalaxy && selection?.kind !== 'region') crumbItems.push({ key: 'g:' + ctxGalaxy, label: galaxyName(cosmos, ctxGalaxy, lang), onClick: () => flyToGalaxy(ctxGalaxy) });
    if (selection?.kind === 'star') crumbItems.push({ key: 's:' + selection.star.id, label: tx(selection.star.name, lang) });
  }
  const collapse = crumbItems.length > 3;
  const hiddenCrumbs = collapse ? crumbItems.slice(1, crumbItems.length - 2) : [];
  const shownCrumbs = collapse ? [crumbItems[0]!, ...crumbItems.slice(crumbItems.length - 2)] : crumbItems;
  const crumbButton = (it: (typeof crumbItems)[number], last: boolean) =>
    last || !it.onClick ? (
      <span className="uv-crumb-current" title={it.label}>
        {it.label}
      </span>
    ) : (
      <button type="button" onClick={it.onClick} title={it.label}>
        {it.label}
      </button>
    );
  const crumbs = (
    <nav className="uv-crumbs" aria-label={t('uni.places')}>
      {shownCrumbs.map((it, i) => (
        <span key={it.key} className={'uv-crumb' + (i === shownCrumbs.length - 1 ? ' last' : '')}>
          {i > 0 && <Icon name="chevronRight" size={14} />}
          {collapse && i === 1 && (
            <>
              <button
                type="button"
                className="uv-crumb-more"
                aria-expanded={crumbMenu}
                aria-label={hiddenCrumbs.map((h) => h.label).join(' › ')}
                title={hiddenCrumbs.map((h) => h.label).join(' › ')}
                onClick={() => setCrumbMenu((v) => !v)}
              >
                …
              </button>
              <Icon name="chevronRight" size={14} />
            </>
          )}
          {crumbButton(it, i === shownCrumbs.length - 1 && crumbItems.length > 1)}
        </span>
      ))}
      {crumbMenu && hiddenCrumbs.length > 0 && (
        <ul className="uv-crumb-menu" role="menu">
          {hiddenCrumbs.map((h) => (
            <li key={h.key}>
              <button
                type="button"
                role="menuitem"
                onClick={() => {
                  setCrumbMenu(false);
                  h.onClick?.();
                }}
              >
                {h.label}
              </button>
            </li>
          ))}
        </ul>
      )}
    </nav>
  );

  return (
    <div className={'universe' + (placesOpen ? ' places-open' : '') + (selection ? ' has-selection' : '')}>
      <div className="uv-view">
        <div ref={hostRef} className="viewport" />
        {status === 'loading' && (
          <div className="view-loading" role="status">
            <span className="spinner" />
            {t('uni.loadingModel')}
          </div>
        )}
        {(status === 'missing' || status === 'error' || status === 'nogl') && (
          <div className="view-banner danger" role="alert">
            <Icon name="warning" size={18} />
            <span>{status === 'missing' ? t('uni.modelMissing') : status === 'nogl' ? t('error.webgl') : t('uni.modelError', { reason: errText })}</span>
          </div>
        )}
      </div>

      <header className="uv-bar">
        <button type="button" className="icon-btn panel-toggle" onClick={() => setPlacesOpen((v) => !v)} aria-pressed={placesOpen} title={t('uni.places')} aria-label={t('uni.places')}>
          <Icon name="layers" />
        </button>
        {crumbs}
        <div className="uv-search">
          <div className="search-box sm">
            <Icon name="search" size={16} />
            <input
              className="input"
              value={q}
              placeholder={t('uni.search')}
              aria-label={t('uni.search')}
              onChange={(e) => {
                setQ(e.target.value);
                setSearchOpen(true);
              }}
              onFocus={() => setSearchOpen(true)}
              onBlur={() => window.setTimeout(() => setSearchOpen(false), 160)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && hits[0]) {
                  const h = hits[0];
                  if (h.kind === 'region') flyToRegion(h.id);
                  else if (h.kind === 'galaxy') flyToGalaxy(h.id);
                  else if (h.kind === 'star') flyToStar(h.star);
                  else if (h.kind === 'unplaced') {
                    select(null);
                    setUnplaced(h.known);
                  }
                  setSearchOpen(false);
                  (e.target as HTMLInputElement).blur();
                }
                if (e.key === 'Escape') {
                  setQ('');
                  (e.target as HTMLInputElement).blur();
                }
              }}
            />
          </div>
          {searchOpen && q.trim() && (
            <ul className="uv-results" role="listbox">
              {hits.length === 0 && <li className="uv-result empty">{t('common.noResults', { q })}</li>}
              {hits.map((h, i) => (
                <li key={i}>
                  <button
                    type="button"
                    className={'uv-result' + (h.kind === 'error' ? ' error' : '')}
                    disabled={h.kind === 'error'}
                    onMouseDown={(e) => e.preventDefault()}
                    onClick={() => {
                      if (h.kind === 'region') flyToRegion(h.id);
                      else if (h.kind === 'galaxy') flyToGalaxy(h.id);
                      else if (h.kind === 'star') flyToStar(h.star);
                      else if (h.kind === 'unplaced') {
                        select(null);
                        setUnplaced(h.known);
                      }
                      setSearchOpen(false);
                    }}
                  >
                    <Icon name={h.kind === 'galaxy' ? 'galaxy' : h.kind === 'region' ? 'target' : h.kind === 'error' ? 'warning' : 'star'} size={16} />
                    <span className="uv-result-text">
                      <span>{h.title}</span>
                      <span className="faint small">{h.sub}</span>
                    </span>
                    {h.kind === 'star' && (h.star.provenance === 'observed' ? provenanceBadge('observed', t) : provenanceBadge('procedural', t))}
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
        <div className="uv-bar-right">
          <button type="button" className="tool-btn" onClick={overview} disabled={!cosmos} title={t('uni.homeTitle')} aria-label={t('uni.homeTitle')}>
            <Icon name="home" />
            <span className="tool-label">{t('uni.home')}</span>
          </button>
          <button type="button" className="tool-btn" onClick={nearbyUniverse} disabled={!cosmos} title={t('uni.nearbyUniverse')} aria-label={t('uni.nearbyUniverse')}>
            <Icon name="fit" />
            <span className="tool-label">{t('uni.nearbyUniverse')}</span>
          </button>
          <button type="button" className="tool-btn" onClick={goSun} disabled={!cosmos} title={t('uni.sun')}>
            <Icon name="star" />
            <span className="tool-label">{t('uni.sun')}</span>
          </button>
          <button type="button" className={'tool-btn' + (legendOpen ? ' active' : '')} onClick={() => setLegendOpen((v) => !v)} aria-expanded={legendOpen} title={t('uni.legend.title')} aria-label={t('uni.legend.title')}>
            <Icon name="info" />
          </button>
        </div>
        {legendOpen && (
          <div className="popover uv-legend" role="dialog" aria-label={t('uni.legend.title')}>
            <p className="popover-title">{t('uni.legend.title')}</p>
            <p className="uv-legend-row">{provenanceBadge('observed', t)} {legendText(t('uni.legend.observed'))}</p>
            <p className="uv-legend-row">{provenanceBadge('reconstructed', t)} {legendText(t('uni.legend.reconstructed'))}</p>
            <p className="uv-legend-row">{provenanceBadge('procedural', t)} {legendText(t('uni.legend.procedural'))}</p>
            <p className="faint small">{t('uni.legend.flight')}</p>
            <p className="faint small">{tr('cosmos.no_complete_catalogue', lang)}</p>
            <p className="faint small">{tr('cosmos.galaxy_not_nbody', lang)}</p>
            <p className="faint small">{t('uni.cameraHint')}</p>
          </div>
        )}
      </header>

      {placesOpen && (
        <aside className="panel uv-places" aria-label={t('uni.places')}>
          <div className="panel-head">
            <p className="eyebrow">{t('uni.places')}</p>
            <button type="button" className="icon-btn panel-close" onClick={() => setPlacesOpen(false)} aria-label={t('common.close')}>
              <Icon name="close" />
            </button>
          </div>
          <div className="panel-body">
            <div className="uv-featured">
              {cosmos &&
                FEATURED.filter((id) => cosmos.summary(id)).map((id) => (
                  <button key={id} type="button" className={'uv-place' + (vstate?.galaxyId === id ? ' current' : '')} onClick={() => { closePlacesOnPhone(); flyToGalaxy(id); }} disabled={flying}>
                    <Icon name="galaxy" size={18} />
                    <span className="uv-place-text">
                      <span className="uv-place-name">{galaxyName(cosmos, id, lang)}</span>
                      <span className="uv-place-meta">
                        {id === 'milky_way' ? t('uni.youAreHere') : formatDistance(dist(cosmos.summary(id)!.centrePc, cosmos.sunPc), lang, false)}
                      </span>
                    </span>
                  </button>
                ))}
            </div>
            {cosmos && cosmos.regions.length > 0 && (
              <details className="uv-group" open>
                <summary>
                  {t('uni.regions')} · {cosmos.regions.filter((r) => r.depth === 1).length}
                </summary>
                <ul className="uv-list uv-regions">
                  {cosmos.regionOrder
                    .map((id) => cosmos.region(id))
                    .filter((r): r is NonNullable<typeof r> => !!r && r.depth === 1)
                    .map((r) => (
                      <li key={r.info.id}>
                        <RegionRow c={cosmos} r={r} lang={lang} current={ctxRegions.some((x) => x.info.id === r.info.id)} disabled={flying} onRegion={(id) => { closePlacesOnPhone(); flyToRegion(id); }} onGalaxy={(id) => { closePlacesOnPhone(); flyToGalaxy(id); }} />
                      </li>
                    ))}
                </ul>
              </details>
            )}
            {cosmos && (
              <details className="uv-group">
                <summary>
                  {t('uni.allGalaxies')} · {cosmos.galaxies.length}
                </summary>
                <ul className="uv-list">
                  {cosmos.galaxies
                    .map((g) => ({ g, d: dist(g.centrePc, cosmos.sunPc) }))
                    .sort((a, b) => a.d - b.d)
                    .map(({ g, d }) => (
                      <li key={g.id}>
                        <button type="button" className="uv-row" onClick={() => { closePlacesOnPhone(); flyToGalaxy(g.id); }} disabled={flying}>
                          <span>{galaxyName(cosmos, g.id, lang)}</span>
                          <span className="faint small">{g.id === 'milky_way' ? t('uni.youAreHere') : formatDistance(d, lang, false)}</span>
                        </button>
                      </li>
                    ))}
                </ul>
              </details>
            )}
            {cosmos && cosmos.observed.length > 0 && (
              <details className="uv-group" open>
                <summary>
                  {t('uni.knownStars')} · {cosmos.observed.length}
                </summary>
                <div className="search-box sm">
                  <Icon name="search" size={15} />
                  <input className="input" value={starFilter} onChange={(e) => setStarFilter(e.target.value)} placeholder={t('common.search')} aria-label={t('uni.knownStars')} />
                </div>
                <ul className="uv-list">
                  {observedSorted.map(({ s, d }) => (
                    <li key={s.id}>
                      <button type="button" className={'uv-row' + (selection?.kind === 'star' && selection.star.id === s.id ? ' current' : '')} onClick={() => { closePlacesOnPhone(); flyToStar(s); }} disabled={flying}>
                        <span className="uv-row-name">
                          <span className="prov-dot obs" aria-hidden="true" />
                          {tx(s.name, lang)}
                          {sceneIdOf(s) && <Icon name="sandbox" size={13} />}
                        </span>
                        <span className="faint small">{d < 1e-6 ? t('uni.youAreHere') : formatDistance(d, lang, false)}</span>
                      </button>
                    </li>
                  ))}
                </ul>
              </details>
            )}
          </div>
        </aside>
      )}

      {selection && cosmos && selection.kind !== 'point' && (
        <aside className="panel uv-card" aria-label={t('uni.select')}>
          <button type="button" className="icon-btn uv-card-close" onClick={() => select(null)} aria-label={t('common.close')}>
            <Icon name="close" />
          </button>
          <div className="panel-body">
            {selection.kind === 'region' ? (
              <RegionCard c={cosmos} id={selection.regionId} flying={flying} onFly={() => flyToRegion(selection.regionId)} onGalaxy={flyToGalaxy} onRegion={flyToRegion} />
            ) : selection.kind === 'galaxy' ? (
              <GalaxyCard c={cosmos} id={selection.galaxyId} flying={flying} onFly={() => flyToGalaxy(selection.galaxyId)} onOverview={nearbyUniverse} onRegion={flyToRegion} />
            ) : (
              <StarCard c={cosmos} star={selection.star} flying={flying} onFly={() => flyToStar(selection.star)} onEnter={(h) => void enter(selection.star, h)} />
            )}
          </div>
        </aside>
      )}
      {unplaced && !selection && (
        <aside className="panel uv-card compact" aria-label={t('uni.select')}>
          <button type="button" className="icon-btn uv-card-close" onClick={() => setUnplaced(null)} aria-label={t('common.close')}>
            <Icon name="close" />
          </button>
          <div className="panel-body">
            <div className="uv-card-head">
              <p className="eyebrow">{t('uni.observedHost')}</p>
              <h2 className="uv-card-title">{tx(unplaced.name, lang)}</h2>
              <div className="uv-badges">
                {provenanceBadge('observed', t)}
                <span className="uv-galaxy-chip">{t('uni.noPosition')}</span>
              </div>
            </div>
            <p className="muted small">{t('uni.noPositionLong')}</p>
            {unplaced.sceneId && (
              <div className="uv-actions">
                <button type="button" className="btn btn-lilac" onClick={() => void enterCatalogueScene(unplaced.sceneId!, tx(unplaced.name, lang), null)}>
                  <Icon name="sandbox" size={17} />
                  {t('uni.openScene')}
                </button>
              </div>
            )}
          </div>
        </aside>
      )}
      {selection?.kind === 'point' && cosmos && (
        <aside className="panel uv-card compact" aria-label={t('uni.select')}>
          <button type="button" className="icon-btn uv-card-close" onClick={() => select(null)} aria-label={t('common.close')}>
            <Icon name="close" />
          </button>
          <div className="panel-body">
            <p className="eyebrow">{galaxyName(cosmos, selection.galaxyId, lang)}</p>
            <p className="muted small">{t('uni.distanceSun')}: {formatDistance(dist(selection.positionPc, cosmos.sunPc), lang)}</p>
            <div className="uv-actions">
              <button type="button" className="btn btn-primary" disabled={flying} onClick={() => void fly(selection.positionPc, POINT_VIEW_PC, galaxyName(cosmos, selection.galaxyId, lang))}>
                <Icon name="target" size={17} />
                {reduced ? t('uni.jumpTo') : t('uni.flyTo')}
              </button>
            </div>
          </div>
        </aside>
      )}

      <footer className="uv-hud">
        {flight ? (
          <div className="uv-flight" role="status">
            <div className="uv-flight-top">
              <span className="eyebrow">{t('uni.flight.title')}</span>
              <span className="uv-flight-route">{t('uni.flight.route', { from: flight.fromName, to: flight.toName })}</span>
            </div>
            <div className="uv-progress" aria-hidden="true">
              <span style={{ width: `${Math.round(flight.t * 100)}%` }} />
            </div>
            <div className="uv-flight-row">
              <span className="num">{t('uni.flight.remaining', { d: formatDistance(flight.remainingPc, lang, false) })}</span>
              <span className="faint small uv-flight-note">{t('uni.flight.note', { t: lightTime(flight.totalPc, lang) })}</span>
              <div className="uv-flight-buttons">
                <label className="uv-speed">
                  <span className="sr-only">{t('uni.flight.speed')}</span>
                  <select value={speed} onChange={(e) => setSpeed(Number(e.target.value))} aria-label={t('uni.flight.speed')}>
                    <option value={0.5}>×0.5</option>
                    <option value={1}>×1</option>
                    <option value={2}>×2</option>
                    <option value={4}>×4</option>
                  </select>
                </label>
                <button
                  type="button"
                  className="btn btn-sm"
                  onClick={() => {
                    skipRef.current = true;
                    viewRef.current?.stopFlight();
                  }}
                >
                  {t('uni.flight.skip')}
                </button>
                <button type="button" className="btn btn-sm btn-danger-ghost" onClick={() => viewRef.current?.stopFlight()}>
                  {t('uni.flight.stop')}
                </button>
              </div>
            </div>
          </div>
        ) : (
          <div className="uv-coverage">
            <span className="uv-scale num">{vstate ? t('uni.fov', { d: formatDistance(vstate.viewWidthPc, lang, false) }) : '—'}</span>
            {capText && <span className="uv-cov">{capText}</span>}
            {sampleText && <span className="uv-cov">{sampleText}</span>}
            {nearText && <span className="uv-cov">{nearText}</span>}
            <label className="uv-speed" title={t('uni.flight.speed')}>
              <Icon name="faster" size={14} />
              <select value={speed} onChange={(e) => setSpeed(Number(e.target.value))} aria-label={t('uni.flight.speed')}>
                <option value={0.5}>×0.5</option>
                <option value={1}>×1</option>
                <option value={2}>×2</option>
                <option value={4}>×4</option>
              </select>
            </label>
          </div>
        )}
      </footer>
    </div>
  );
}

export default UniversePage;

export type { LocalizedText };
